return ['project-id-version'=>'Lingua Forge 2.1.0','report-msgid-bugs-to'=>'https://wordpress.org/support/plugin/lingua-forge','last-translator'=>'admin','language-team'=>'Italian','mime-version'=>'1.0','content-type'=>'text/plain; charset=UTF-8','content-transfer-encoding'=>'8bit','pot-creation-date'=>'2026-06-01T15:14:22+00:00','po-revision-date'=>'2026-06-08 19:23+0000','x-generator'=>'Loco https://localise.biz/','x-domain'=>'lingua-forge','language'=>'it_IT','plural-forms'=>'nplurals=2; plural=n != 1;','x-loco-version'=>'2.8.5; wp-7.0; php-8.3.31','messages'=>['"%1$s %2$s" saved.'=>'"%1$s %2$s" salvato.','"%1$s" created. %2$d template updated.'=>'"%1$s" creato. %2$d modello aggiornato.' . "\0" . '"%1$s" creato. %2$d modelli aggiornati.','"%s" created.'=>'"%s" creato.','"product" (replaces "article")'=>'"prodotto" (sostituisce "articolo")','%1$d chars — good, slightly above the ideal %2$d but within the accepted %3$d-char range. %4$s'=>'%1$d caratteri — buono, leggermente sopra il massimo ideale %2$d ma entro l\'intervallo accettato di %3$d caratteri. %4$s','%1$d chars — ideal length. %2$s'=>'%1$d caratteri — lunghezza ideale. %2$s','%1$d chars — likely truncated in SERPs (keep under %2$d). %3$s'=>'%1$d caratteri — probabilmente troncati nei risultati di ricerca (mantieni sotto %2$d). %3$s','%1$d chars — too short (aim for %2$d–%3$d). %4$s'=>'%1$d caratteri — troppo breve (punta a %2$d–%3$d). %4$s','%1$d chars, %2$d words — good title.'=>'%1$d caratteri, %2$d parole — buon titolo.','%1$d internal, %2$d external.'=>'%1$d interni, %2$d esterni.','%1$d of %2$d image(s) missing alt text.'=>'%1$d di %2$d immagini mancano di testo alternativo.','%1$d post tagged with _lf_lang = %2$s.'=>'%1$d post contrassegnato con _lf_lang = %2$s.' . "\0" . '%1$d post contrassegnati con _lf_lang = %2$s.','%1$d words — below recommended minimum of %2$d.'=>'%1$d parole — al di sotto del minimo consigliato di %2$d.','%1$d words — very thin content. Consider expanding to at least %2$d words.'=>'%1$d parole — contenuto molto scarso. Considera di espandere ad almeno %2$d parole.','%d external link(s), no internal links.'=>'%d link esterni, nessun link interno.','%d external link(s), no internal links. Add internal links to related content.'=>'%d link esterni, nessun link interno. Aggiungi link interni ai contenuti correlati.','%d H1 tags found — a page should have exactly one H1.'=>'%d tag H1 trovati — una pagina dovrebbe avere esattamente un H1.','%d image(s), all have alt text.'=>'%d immagini, tutte hanno testo alternativo.','%d language not yet linked'=>'%d lingua non ancora collegata' . "\0" . '%d lingue non ancora collegate','%d link updated.'=>'%d collegamento aggiornato.' . "\0" . '%d collegamenti aggiornati.','%d locale file could not be removed automatically (DISALLOW_FILE_MODS is set). Delete it manually via your server or WP-CLI: wp language core uninstall <locale>'=>'%d file di lingua non sono stati rimossi automaticamente (DISALLOW_FILE_MODS è impostato). Eliminali manualmente tramite il tuo server o WP-CLI: wp language core uninstall <locale>.' . "\0" . '%d file di lingua non sono stati rimossi automaticamente (DISALLOW_FILE_MODS è impostato). Eliminali manualmente tramite il tuo server o WP-CLI: wp language core uninstall <locale>.','%d locale file removed.'=>'%d file di lingua rimossi.' . "\0" . '%d file di lingua rimossi.','%d locale pack installed.'=>'%d pacchetto di localizzazione installato.' . "\0" . '%d pacchetti di localizzazione installati.','%d navigation reference updated.'=>'%d riferimento di navigazione aggiornato.' . "\0" . '%d riferimenti di navigazione aggiornati.','%d part reference updated.'=>'%d riferimento alla parte aggiornato.' . "\0" . '%d riferimenti alle parti del modello aggiornati.','%d post'=>'%d post' . "\0" . '%d post','%d rule registered'=>'%d regola registrata' . "\0" . '%d regole registrate','%d words.'=>'%d parole.','%s Archive'=>'%s Archivio','%s is active and already outputs Schema.org JSON-LD. Lingua Forge has disabled its own schema output to prevent conflicting graphs. Unlike Open Graph — where LF adds og:locale on top of another plugin\'s output — schema cannot be cleanly supplemented: duplicate or overlapping JSON-LD graphs produce validation errors. Disable schema output in the detected plugin if you want LF to handle structured data.'=>'%s è attivo e già genera JSON-LD Schema.org. Lingua Forge ha disabilitato la propria uscita schema per evitare grafici in conflitto. A differenza di Open Graph — dove LF aggiunge og:locale sopra l\'output di un altro plugin — lo schema non può essere integrato pulitamente: grafici JSON-LD duplicati o sovrapposti producono errori di validazione. Disabilita l\'output schema nel plugin rilevato se vuoi che LF gestisca i dati strutturati.','%s is active and generates its own sitemap. That sitemap is separate from LF\'s. Both should be submitted to Google Search Console: the SEO plugin sitemap lists your content; the LF sitemap adds the multilingual alternate links. LF\'s sitemap is announced in robots.txt automatically.'=>'%s è attivo e genera la propria mappa del sito. Questa mappa è separata da quella di LF. Entrambe devono essere inviate a Google Search Console: la mappa del sito del plugin SEO elenca i tuoi contenuti; la mappa di LF aggiunge i link alternativi multilingue. La mappa di LF viene annunciata automaticamente in robots.txt.','(avg %.1f hits/block)'=>'(media %.1f colpi/blocco)','(avg %.1f hits/entry)'=>'(media %.1f colpi/voce)','(classic theme)'=>'(tema classico)','(disabled)'=>'disabilitato','(FSE / block theme)'=>'(tema FSE / blocco)','(no title) #%d'=>'(senza titolo) #%d','({skipped} had no replaceable links — re-scan to investigate)'=>'({skipped} non aveva link sostituibili — riscaricare per indagare)','.txt file(s) in the directory'=>'.txt file(i) nella directory','/ 100'=>'/ 100','1 H1 ✓ — no H2 subheadings (acceptable for this content type).'=>'1 H1 ✓ — nessun sottotitolo H2 (accettabile per questo tipo di contenuto).','1 H1 ✓ — no H2 subheadings found. Adding H2s improves structure.'=>'1 H1 ✓ — nessun sottotitolo H2 trovato. Aggiungere H2 migliora la struttura.','1 H1 ✓, %1$d H2, %2$d H3.'=>'1 H1 ✓, %1$d H2, %2$d H3.','<strong>Lingua Forge:</strong> %1$d localized template(s) from the &#8220;%2$s&#8221; theme are preserved in the database but are currently inactive. They will become active again if you reactivate that theme. To carry your translations to the new theme, regenerate them via <strong>Settings → Lingua Forge → Router → FSE scaffold</strong>.'=>'<strong>Lingua Forge:</strong> %1$d modello(i) localizzato(i) dal tema &#8220;%2$s&#8221; sono conservati nel database ma attualmente inattivi. Diventeranno di nuovo attivi se riattivi quel tema. Per trasferire le tue traduzioni al nuovo tema, rigenerale tramite <strong>Impostazioni → Lingua Forge → Router → FSE scaffold</strong>.','<strong>{n}</strong> auto-fixable link(s)'=>'<strong>{n}</strong> link automaticamente correggibili','<strong>{n}</strong> link(s) needing manual review'=>'<strong>{n}</strong> link che necessitano revisione manuale','<strong>{n}</strong> stale path(s)'=>'<strong>{n}</strong> percorso(i) obsoleto(i)','<strong>{n}</strong> template issue(s)'=>'<strong>{n}</strong> problema(i) di template','_lf_lang Coverage'=>'Copertura _lf_lang','A physical robots.txt file exists at the site root. WordPress\'s virtual robots.txt — and LF\'s Sitemap: filter — are bypassed. The LF sitemap is not announced to search engines.'=>'Esiste un file robots.txt fisico nella radice del sito. Il robots.txt virtuale di WordPress — e il filtro Sitemap di LF — sono bypassati. La mappa del sito di LF non viene annunciata ai motori di ricerca.','Accepts compiled .mo files only. Filename must follow the pattern {textdomain}-{locale}.mo. Uploading a file with the same name as an existing one will replace it.'=>'Accetta solo file .mo compilati. Il nome del file deve seguire il modello {textdomain}-{locale}.mo. Caricare un file con lo stesso nome di uno esistente lo sostituirà.','Action'=>'Azione','active'=>'attivo','Active Languages'=>'Lingue attive','Active languages'=>'Lingue attive','Active languages: add each language you want to support. Each language gets a URL prefix or subdomain and an hreflang tag in the page &lt;head&gt;.'=>'Lingue attive: aggiungi ogni lingua che desideri supportare. Ogni lingua ottiene un prefisso URL o un sottodominio e un tag hreflang nell\'&lt;head&gt; della pagina.','Active preset'=>'Predefinito attivo','Active Provider'=>'Provider attivo','Active provider'=>'Provider attivo','Active theme'=>'Tema attivo','Active: %s.'=>'Attivo: %s.','Add entry'=>'Aggiungi voce','Add instructions to improve the draft — e.g. make it shorter, add a conclusion section, use a more formal register, include an FAQ block…'=>'Aggiungi istruzioni per migliorare la bozza — ad esempio, renderla più breve, aggiungere una sezione conclusiva, usare un registro più formale, includere un blocco FAQ…','Add instructions to improve the draft — e.g. make it shorter, add a conclusion section, use a more formal register…'=>'Aggiungi istruzioni per migliorare la bozza — ad esempio, renderla più breve, aggiungere una sezione di conclusione, usare un registro più formale…','Add key →'=>'Aggiungi chiave →','Add new entry'=>'Aggiungi nuova voce','Add one term per row. Both the source term and the target rendering are required. The language pair determines which translation jobs the constraint applies to.'=>'Aggiungi un termine per riga. Sia il termine di origine che la resa target sono necessari. La coppia di lingue determina a quali lavori di traduzione si applica la restrizione.','Add Sitemap directive to robots.txt'=>'Aggiungi direttiva Sitemap a robots.txt','Add the following line to your robots.txt manually:'=>'Aggiungi la seguente riga a robots.txt manualmente:','Add WooCommerce product tags to Open Graph output'=>'Aggiungi tag prodotto WooCommerce all\'output Open Graph','Adds a link to the home page so visitors can browse in their language.'=>'Aggiunge un link alla pagina principale così i visitatori possono navigare nella loro lingua.','Administrators only (manage_options)'=>'Solo amministratori (manage_options)','After changing the primary language, flush permalinks (section below) for the URL routing to update.'=>'Dopo aver cambiato la lingua principale, svuota i permalink (sezione sotto) affinché l\'aggiornamento della struttura URL venga applicato.','After changing URL structure settings (path prefix ↔ subdomain), always visit Settings → Permalinks and click Save Changes to flush the rewrite rules.'=>'Dopo aver modificato le impostazioni della struttura URL (prefisso del percorso ↔ sottodominio), visita sempre Impostazioni → Permalink e clicca su Salva modifiche per svuotare le regole di riscrittura.','AI analysis failed. Please try again.'=>'Analisi AI fallita. Riprova.','AI Behaviour Preset'=>'Preset di comportamento AI','AI cache cleared. %d entry was removed.'=>'Cache AI cancellata. %d voce è stata rimossa.' . "\0" . 'Cache AI cancellata. %d voci sono state rimosse.','AI Cache: lists cached AI responses with hit counts. Clear the whole cache or a single post\'s entries. Use "Clear" before testing a translation change — cached results are returned even when you change the AI preset or model until the cache entry is evicted.'=>'Cache AI: elenca le risposte AI memorizzate con i conteggi di accesso. Cancella l\'intera cache o le voci di un singolo post. Usa "Cancella" prima di testare una modifica di traduzione — i risultati memorizzati vengono restituiti anche quando cambi il preset o il modello AI fino a quando la voce della cache non viene rimossa.','AI Configuration'=>'Configurazione AI','AI features are optional. Language routing, hreflang, the language switcher, and the translation group system all work without a provider configured.'=>'Le funzionalità AI sono opzionali. Il routing linguistico, hreflang, il switcher di lingua e il sistema di gruppi di traduzione funzionano tutti senza un provider configurato.','AI Limits & Security'=>'Limiti e sicurezza dell\'IA','AI provider returned an empty response.'=>'Il provider AI ha restituito una risposta vuota.','AI Recommendations'=>'Raccomandazioni AI','AI returned an unexpected response format. Please try again.'=>'L\'AI ha restituito un formato di risposta inaspettato. Riprova.','AI translation and batch analysis may time out. Recommend 120s or more.'=>'La traduzione AI e l\'analisi batch potrebbero scadere. Si consiglia 120s o più.','AI Usage'=>'Utilizzo AI','AI Usage & Cache'=>'Utilizzo AI & Cache','Aim for 120–160 characters. Leave empty to use the excerpt fallback.'=>'Obiettivo di 120–160 caratteri. Lascia vuoto per usare il fallback dell\'estratto.','All major search engines — Google, Bing, and Yandex — discover the sitemap automatically via the Sitemap: directive in robots.txt. No manual action is required. The buttons below send an immediate ping so the engine recrawls the sitemap now rather than waiting for its next scheduled robots.txt check.'=>'Tutti i principali motori di ricerca — Google, Bing e Yandex — scoprono automaticamente la mappa del sito tramite la direttiva Sitemap: in robots.txt. Non è richiesta azione manuale. I pulsanti sottostanti inviano un ping immediato affinché il motore ricrawli la mappa del sito ora, anziché aspettare il prossimo controllo programmato di robots.txt.','All published posts have a _lf_lang value. No gaps detected.'=>'Tutti i post pubblicati hanno un valore _lf_lang. Nessuna lacuna rilevata.','All time'=>'Tutto il tempo','All types'=>'Tutti i tipi','Allow editors to lock individual blocks'=>'Consenti agli editor di bloccare blocchi individuali','Allow Gutenberg template-editing mode on post screens'=>'Consenti la modalità di modifica modello di Gutenberg nelle schermate dei post','Also delete language assignments, translation relationships, meta descriptions, glossary, and Translation Memory when the plugin is uninstalled'=>'Elimina anche assegnazioni di lingua, relazioni di traduzione, meta descrizioni, glossario e memoria di traduzione quando il plugin viene disinstallato','Also generate meta description'=>'Genera anche meta descrizione','Alternative (server-side):'=>'Alternativa (lato server):','Always emit only og:locale and og:locale:alternate. Use when another plugin or theme handles the full OG set.'=>'Emetti sempre solo og:locale e og:locale:alternate. Usalo quando un altro plugin o tema gestisce l\'intero set OG.','Always emit the complete OG + Twitter Card set regardless of other plugins. Use only if no other plugin outputs OG tags.'=>'Emetti sempre l\'intero set OG + Twitter Card indipendentemente dagli altri plugin. Usalo solo se nessun altro plugin genera tag OG.','An unknown error occurred.'=>'Si è verificato un errore sconosciuto.','Analyse'=>'Analizza','Analyse all languages'=>'Analizza tutte le lingue','Analyse…'=>'Analizza…','Analysis'=>'Analisi','Analysis request failed. Please try again.'=>'Richiesta di analisi fallita. Riprova.','Analyzing…'=>'Analisi in corso…','and'=>'e','Anthropic (Claude)'=>'Anthropic (Claude)','any'=>'qualsiasi','API calls saved by cache'=>'Chiamate API salvate dalla cache','API Key'=>'Chiave API','API key'=>'Chiave API','API Keys'=>'Chiavi API','API Keys Tab'=>'Scheda Chiavi API','API Response Cache'=>'Cache delle risposte API','API Response Cache setting saved.'=>'Impostazione cache di risposta API salvata.','Appends the following line to your existing robots.txt: %s'=>'Aggiunge la seguente riga al tuo robots.txt esistente: %s','Applied ✓'=>'Applicato ✓','Apply failed — please try again.'=>'Applicazione fallita — riprova.','Apply to all language versions'=>'Applica a tutte le versioni linguistiche','Apply to Block'=>'Applica al blocco','Apply to Editor'=>'Applica all\'Editor','Apply to Footnote'=>'Applica alla nota a piè di pagina','Apply to Meta Description'=>'Applica alla Meta Description','Apply translation'=>'Applica traduzione','Applying…'=>'Applicazione in corso…','Approximate size'=>'Dimensione approssimativa','Archive'=>'Archivio','Archive: %s'=>'Archivio: %s','Article / WebPage'=>'Articolo / Pagina Web','Article / WebPage — all singular posts and pages'=>'Articolo / Pagina Web — tutti i post e pagine singoli','Authors and above (edit_published_posts)'=>'Autori e superiori (edit_published_posts)','Auto (recommended)'=>'Auto (raccomandato)','Auto-detect assigns: WooCommerce products → Product profile; the static front page → Landing profile; everything else → Blog profile. Choose a specific profile to override this for all posts.'=>'L\'assegnazione automatica: prodotti WooCommerce → Profilo prodotto; la pagina statica iniziale → Profilo di destinazione; tutto il resto → Profilo blog. Scegli un profilo specifico per sovrascrivere questa impostazione per tutti i post.','Batch Analysis'=>'Analisi batch','Behavior'=>'Comportamento','Behavior: choose the AI preset (Literal, Balanced, Creative), add site-wide custom prompt instructions, enable or disable automatic post-save translation, and configure the Translation Memory.'=>'Comportamento: scegli il preset AI (Letterale, Bilanciato, Creativo), aggiungi istruzioni personalizzate a livello di sito, abilita o disabilita la traduzione automatica dopo il salvataggio del post e configura la Memoria di Traduzione.','Block Content'=>'Contenuto del blocco','block descriptionRenders a polite notice when the current page is being shown in its source language because no translation exists for the visitor\'s language. Driven by the Lingua Forge router\'s LINGUAFORGE_LANG_FALLBACK_ACTIVE signal — emits nothing when a translation exists for the request locale.'=>'Visualizza un avviso cortese quando la pagina corrente viene mostrata nella sua lingua originale perché non esiste una traduzione per la lingua del visitatore. Guidato dal segnale LINGUAFORGE_LANG_FALLBACK_ACTIVE del router di Lingua Forge — non emette nulla quando esiste una traduzione per la località richiesta.','Block Editor'=>'Editor a blocchi','block keywordfallback'=>'fallback','block keywordi18n'=>'i18n','block keywordlanguage'=>'lingua','block keywordlinguaforge'=>'linguaforge','block keywordtranslation'=>'traduzione','Block locking'=>'Blocco di blocco','Block patterns registered for custom post types. Use the Translate button to produce a language variant. The translated content is saved here and can be copied into any CPT post from the block editor Pattern inserter or used as a starting point for a Synced Pattern (Reusable Block).'=>'Modelli registrati per tipi di post personalizzati. Usa il pulsante Traduci per produrre una variante linguistica. Il contenuto tradotto viene salvato qui e può essere copiato in qualsiasi post CPT dall\'inseritore di modelli dell\'editor a blocchi o usato come punto di partenza per un Modello Sincronizzato (Blocco Riutilizzabile).','block titleMissing Translation Notice'=>'Avviso di traduzione mancante','Block translation reuses'=>'Riutilizzo delle traduzioni di blocco','Block-level translation cache shared across posts. When enabled, identical blocks (same markup, language pair, and glossary) are served from memory instead of calling the AI again. Glossary edits and Compliance preset changes automatically invalidate affected cached translations.'=>'Cache di traduzione a livello di blocco condivisa tra i post. Quando abilitata, blocchi identici (stesso markup, coppia di lingue e glossario) vengono serviti dalla memoria invece di chiamare di nuovo l\'AI. Le modifiche al glossario e le modifiche al preset di conformità invalidano automaticamente le traduzioni memorizzate nella cache interessate.','Blog / Editorial'=>'Blog / Editoriale','Blog posts use Article; all other post types and pages use WebPage. Includes headline, description, inLanguage, url, datePublished, dateModified, image, and publisher.'=>'I post del blog usano Articolo; tutti gli altri tipi di post e pagine usano Pagina Web. Include titolo, descrizione, inLanguage, url, data di pubblicazione, data di modifica, immagine e editore.','Browser language redirect'=>'Reindirizzamento della lingua del browser','Built-in preset instructions:'=>'Istruzioni predefinite incorporate:','Bulletize (•-prefixed)'=>'Elenca (prefisso •)','cached'=>'catturato','Cached API responses'=>'Risposte API memorizzate nella cache','Cached block translations'=>'Traduzioni di blocco memorizzate nella cache','Cancel'=>'Annulla','Cannot determine target language from slug.'=>'Impossibile determinare la lingua di destinazione dallo slug.','Cannot write to product %1$d: it is a translated version (language: %2$s)%3$s. Operational data (price, stock, SKU, dimensions) must be updated on the source product. Resolve the source product ID via: GET /wp-json/lingua-forge/v1/post/%4$d/translations'=>'Impossibile scrivere nel prodotto %1$d: è una versione tradotta (lingua: %2$s)%3$s. I dati operativi (prezzo, stock, SKU, dimensioni) devono essere aggiornati sul prodotto originale. Risolvi l\'ID del prodotto sorgente tramite: GET /wp-json/lingua-forge/v1/post/%4$d/translations','Canonical tag'=>'Tag canonico','Cap how much AI usage the site can generate and restrict which user roles may trigger paid AI calls. Sits on top of the per-user rate limit (30 requests / minute, hardcoded) that already protects against single-user runaway loops.'=>'Limita l\'uso dell\'IA che il sito può generare e restringe quali ruoli utente possono attivare chiamate IA a pagamento. Si sovrappone al limite di richiesta per utente (30 richieste / minuto, hardcoded) che già protegge da loop incontrollati di singoli utenti.','Cart'=>'Carrello','chars'=>'caratteri','Checkout'=>'Pagamento','Chunk translated'=>'Porzione tradotta','Chunk translated to:'=>'Porzione tradotta in:','Clear'=>'Cancella','Clear All'=>'Cancella tutto','Clear all cached AI results? Future requests will trigger fresh API calls until the cache rebuilds.'=>'Eliminare tutti i risultati AI memorizzati nella cache? Le richieste future attiveranno chiamate API fresche fino a quando la cache non si ricostruisce.','Clear API Response Cache'=>'Cancella cache delle risposte API','Clear Debug Files'=>'Cancella file di debug','Clear hints'=>'Cancella suggerimenti','Clear input'=>'Cancella input','Clear the entire Translation Memory? Future translations will rebuild the cache as they run.'=>'Cancellare l\'intera memoria di traduzione? Le traduzioni future ricostruiranno la cache man mano che vengono eseguite.','Clear Translation Memory'=>'Cancella memoria di traduzione','Close'=>'Chiudi','Close language panel'=>'Chiudi pannello lingua','Close popover'=>'Chiudi il popover','Compatibility'=>'Compatibilità','Compliance Preset'=>'Predefinito di conformità','Configure an AI provider in Settings → API Keys to enable AI-powered recommendations.'=>'Configura un provider AI in Impostazioni → Chiavi API per abilitare le raccomandazioni AI.','Configure hreflang, Open Graph, Schema.org, sitemaps, and social sharing for every language on your site. Each section below handles one aspect of multilingual SEO.'=>'Configura hreflang, Open Graph, Schema.org, sitemap e condivisione sociale per ogni lingua del tuo sito. Ogni sezione di seguito gestisce un aspetto della SEO multilingue.','Configured'=>'Configurato','Content generated'=>'Contenuto generato','Content Generator'=>'Generatore di contenuti','Content ready'=>'Contenuto pronto','Contributors and above — default (edit_posts)'=>'Contributori e superiori — predefinito (edit_posts)','Control how much content is sent to the AI and how large the response can be. Leave a field blank to use the built-in default (shown as placeholder). Raise these values if large pages are being cut off; lower them to reduce API costs.'=>'Controlla quanto contenuto viene inviato all\'IA e quanto può essere grande la risposta. Lascia vuoto per usare il valore predefinito integrato (mostrato come segnaposto). Aumenta questi valori se le pagine grandi vengono tagliate; riducili per ridurre i costi API.','Controls the token budget and input limits for the AI Content Generator feature. Leave fields blank to use the built-in defaults.'=>'Controlla il budget di token e i limiti di input per la funzione Generatore di contenuti AI. Lascia i campi vuoti per usare i valori predefiniti integrati.','Controls what happens when an administrator deletes the plugin from Plugins → Installed Plugins → Delete. Plugin settings and AI caches are always removed. Language assignments and translation relationships are kept by default so an accidental uninstall or a reinstall can pick up where it left off.'=>'Controlla cosa succede quando un amministratore disinstalla il plugin da Plugins → Plugin installati → Elimina. Le impostazioni del plugin e le cache AI vengono sempre rimosse. Assegnazioni di lingua e relazioni di traduzione sono mantenute di default in modo che una disinstallazione accidentale o una reinstallazione possano riprendere da dove avevano lasciato.','Conversational'=>'Conversazionale','Copied ✓'=>'Copiato ✓','Copied!'=>'Copiato!','Copy'=>'Copia','Copy and paste into a GitHub issue or support request.'=>'Copia e incolla in un problema GitHub o richiesta di supporto.','Copy failed — please copy the URL manually.'=>'Copia fallita — copia manualmente l\'URL.','Copy markup'=>'Copia markup','Copy system info'=>'Copia info sistema','Copy the current URL to the clipboard. Shows a "Link copied" toast on success.'=>'Copia l\'URL corrente negli appunti. Mostra un toast "Link copiato" in caso di successo.','Copy the result and paste it wherever needed (e.g. directly into the footnote field).'=>'Copia il risultato e incollalo dove necessario (ad esempio direttamente nel campo della nota a piè di pagina).','Copy to safe storage'=>'Copia in archiviazione sicura','copy/native/auto JS actions: handled by LF\'s social-share.js'=>'azioni JS copy/native/auto: gestite da LF\'s social-share.js','Could not add entry: source term and target term are required.'=>'Impossibile aggiungere la voce: sono necessari il termine di origine e quello di destinazione.','Could not copy the file. Check that the uploads folder is writable.'=>'Impossibile copiare il file. Verifica che la cartella uploads sia scrivibile.','Could not instantiate the provider.'=>'Impossibile istanziare il provider.','Could not save the file. Check that the uploads folder is writable.'=>'Impossibile salvare il file. Verifica che la cartella uploads sia scrivibile.','Could not save the glossary entry.'=>'Impossibile salvare la voce del glossario.','Could not write to robots.txt. Check file permissions.'=>'Impossibile scrivere in robots.txt. Controlla i permessi del file.','CPT Block Patterns'=>'Modelli di blocco CPT','Create'=>'Crea','Create missing'=>'Creare mancante','Creating translations for post type "%s" requires an active integration. Please ensure the required integration is installed and active.'=>'La creazione di traduzioni per il tipo di post "%s" richiede un\'integrazione attiva. Assicurati che l\'integrazione richiesta sia installata e attiva.','Creating…'=>'Creazione…','Creative / Marketing'=>'Creativo / Marketing','Creative / Marketing instructions'=>'Istruzioni creative / di marketing','Current content (will be overwritten)'=>'Contenuto attuale (sarà sovrascritto)','Current status'=>'Stato attuale','Current title'=>'Titolo attuale','Current: {current}'=>'Attuale: {current}','Currently emitting'=>'Attualmente in emissione','Currently inherited from the %s constant. Selecting a value here will override it.'=>'Attualmente ereditato dalla costante %s. Selezionare un valore qui lo sovrascriverà.','Currently skipped for posts that use block-comment attribute placeholders (wp:details summary fields, etc.) — they fall through to the existing single-call translation path.'=>'Attualmente saltato per i post che usano segnaposto di attributo commento-blocco (wp:details campi di riepilogo, ecc.) — passano alla normale traduzione con chiamata singola.','Currently:'=>'Attualmente:','Custom'=>'Personalizzato','Daily AI quota reached (%1$d requests). Resets at %2$s UTC.'=>'Quota giornaliera di AI raggiunta (%1$d richieste). Si resetta alle %2$s UTC.','Daily quota'=>'Quota giornaliera','Daily request limit'=>'Limite giornaliero di richieste','Danger Zone'=>'Zona di pericolo','Debug Files'=>'File di debug','Debug files cleared. %d file was removed.'=>'File di debug cancellati. %d file sono stati rimossi.' . "\0" . 'File di debug cancellati. %d file sono stati rimossi.','Debug Info'=>'Info di debug','Debug logging'=>'Debug logging','Debug logging disabled.'=>'Debug logging disabilitato.','Debug logging enabled.'=>'Debug logging abilitato.','Debug: enable the debug log to capture AI prompts and API responses to a local file. Disable after troubleshooting — debug mode writes a file on every AI request.'=>'Debug: abilita il registro di debug per catturare i prompt AI e le risposte API in un file locale. Disabilita dopo la risoluzione dei problemi — la modalità di debug scrive un file ad ogni richiesta AI.','Default OG image'=>'Immagine OG predefinita','Default profile'=>'Profilo predefinito','Delete'=>'Elimina','Delete all .txt files in the debug directory? The directory itself will remain so future debug writes still land cleanly.'=>'Eliminare tutti i file .txt nella directory di debug? La directory stessa rimarrà così le future scritture di debug continueranno a essere salvate correttamente.','Delete all files for this override (both .mo and .po)?'=>'Eliminare tutti i file di questa sovrascrittura (sia .mo che .po)?','Delete content data on uninstall'=>'Elimina dati di contenuto alla disinstallazione','Delete this glossary entry?'=>'Eliminare questa voce del glossario?','Describe what to write — topic, key points, structure…'=>'Descrivi cosa scrivere — argomento, punti chiave, struttura…','Details ↗'=>'Dettagli ↗','Detect active SEO plugins (Yoast, Rank Math, etc.) at runtime. Emit only og:locale + og:locale:alternate when another plugin already outputs the full OG set; emit the complete set when none is detected.'=>'Rileva i plugin SEO attivi (Yoast, Rank Math, ecc.) in fase di esecuzione. Emissione solo di og:locale + og:locale:alternate quando un altro plugin già fornisce l\'insieme completo di OG; emette l\'insieme completo quando nessuno viene rilevato.','Directory'=>'Directory','Disable only for headless sites or fully custom hreflang implementations. When disabled, LF no longer removes the WordPress core canonical tag and no longer suppresses SEO-plugin hreflang output.'=>'Disabilita solo per siti headless o implementazioni hreflang completamente personalizzate. Quando disabilitato, LF non rimuove più il tag canonico di WordPress e non sopprime più l\'output hreflang del plugin SEO.','Disabled'=>'Disabilitato','Disabled (by setting)'=>'Disabilitato (impostazione)','Disabled (mode setting)'=>'Disabilitato (impostazione modalità)','Disabled because the lf-social-share mu-plugin is already providing this feature.'=>'Disabilitato perché il mu-plugin lf-social-share fornisce già questa funzione.','DISALLOW_FILE_MODS is set.'=>'DISALLOW_FILE_MODS è impostato.','Display'=>'Visualizza','Displays the Lingua Forge language switcher.'=>'Visualizza il selettore di lingua di Lingua Forge.','Do not output any OG tags.'=>'Non visualizzare alcun tag OG.','Documentation'=>'Documentazione','Done'=>'Fatto','Done — {done} of {total} post(s) fixed.'=>'Fatto — {done} di {total} post corretti.','Down'=>'Giù','Download and install a WordPress core language pack directly from WordPress.org. Once installed, the locale becomes available for URL routing and the AI translation workflow. The list of available languages is fetched on demand — click the button below to load it.'=>'Scarica e installa un pacchetto di lingua di WordPress direttamente da WordPress.org. Una volta installato, il locale diventa disponibile per il routing URL e il flusso di lavoro di traduzione AI. L\'elenco delle lingue disponibili viene recuperato su richiesta — clicca il pulsante sottostante per caricarlo.','Dropdown direction'=>'Direzione del menu a tendina','edit'=>'modifica','Editors and above (edit_others_posts)'=>'Editor e superiori (edit_others_posts)','Enable API response caching'=>'Abilita la cache delle risposte API','Enable block-level translation cache reuse across posts'=>'Riutilizzo della cache di traduzione a livello di blocco tra i post','Enable Social Share URL rewriting for Social Icons blocks'=>'Abilita la riscrittura dell\'URL di Social Share per i blocchi di Icone Social','Enable when your theme renders the post title as an H2 instead of an H1 (common in some block themes). The analyser fetches the rendered page and, if it finds no H1 but does find an H2, it promotes the first H2 to H1 for scoring purposes.'=>'Attiva quando il tuo tema rende il titolo del post come H2 invece di H1 (comune in alcuni temi a blocchi). L\'analizzatore recupera la pagina renderizzata e, se non trova H1 ma trova H2, promuove il primo H2 a H1 per scopi di valutazione.','Enter your API key for at least one AI provider. Keys are encrypted at rest using AES-256-GCM with a site-specific secret (LINGUAFORGE_SECRET). Do not share database exports without rotating the secret first.'=>'Inserisci la tua chiave API per almeno un provider AI. Le chiavi sono criptate a riposo usando AES-256-GCM con un segreto specifico del sito (LINGUAFORGE_SECRET). Non condividere esportazioni del database senza prima ruotare il segreto.','Environment'=>'Ambiente','environment variable'=>'variabile d\'ambiente','Error'=>'Errore','Exclude from navigation menus'=>'Escludi dai menu di navigazione','Expand'=>'Espandi','Expected: {expected}'=>'Previsto: {expected}','External share services'=>'Servizi di condivisione esterni','Extra guidance — tone, style, constraints, target audience…'=>'Guida extra — tono, stile, vincoli, pubblico target…','Extra guidance — tone, style, constraints…'=>'Guida extra — tono, stile, vincoli…','Failed. Please try again.'=>'Fallito. Per favore riprova.','Fallback image URL used when a page has no featured image, site logo, or site icon. Shown in social previews for archives, the blog index, and any singular page without a thumbnail.'=>'URL immagine di fallback usato quando una pagina non ha immagine in evidenza, logo del sito o icona del sito. Mostrato nelle anteprime social per archivi, indice del blog e qualsiasi pagina singola senza anteprima.','Feature'=>'Funzionalità','Features are grouped into two tiers. Enter the exact model identifier for each tier and provider. Leave a field blank to use the built-in default (shown as placeholder). Only the active provider\'s models are called at runtime — configure the others in advance if you plan to switch.'=>'Le funzionalità sono raggruppate in due livelli. Inserisci l\'identificatore esatto del modello per ogni livello e provider. Lascia vuoto per usare il default integrato (mostrato come segnaposto). Solo i modelli del provider attivo vengono chiamati in fase di esecuzione — configura gli altri in anticipo se prevedi di cambiare.','File copied to safe storage successfully.'=>'File copiato in archiviazione sicura con successo.','File modifications are disabled (DISALLOW_FILE_MODS).'=>'Le modifiche ai file sono disabilitate (DISALLOW_FILE_MODS).','Files'=>'File','Files land in the directory below. Useful for diagnosing translation issues — turn off once you have what you need so the files do not accumulate. You can also force this from wp-config.php with `define( \'LINGUAFORGE_AI_DEBUG\', true );` which overrides the toggle.'=>'I file vengono salvati nella directory sottostante. Utile per diagnosticare problemi di traduzione — disattiva una volta ottenuto ciò di cui hai bisogno in modo che i file non si accumulino. Puoi anche forzarlo da wp-config.php con `define( \'LINGUAFORGE_AI_DEBUG\', true );` che sovrascrive l\'interruttore.','Filter'=>'Filtro','Filter by language and post type, browse your content, and click Analyze on any item to run a rule-based SEO audit — title length, meta description, word count, heading structure, image alt coverage, and internal links.'=>'Filtra per lingua e tipo di post, naviga tra i tuoi contenuti e clicca Analizza su qualsiasi elemento per eseguire una verifica SEO basata su regole — lunghezza del titolo, meta descrizione, conteggio parole, struttura degli intestazioni, copertura degli attributi alt delle immagini e link interni.','Filter with linguaforge_debug_dir to redirect debug output to a non-public location.'=>'Filtra con linguaforge_debug_dir per reindirizzare l\'output di debug in una posizione non pubblica.','Finding'=>'Ricerca','Fix'=>'Correggi','Fix All'=>'Correggi tutto','Fix all links'=>'Correggi tutti i link','Fix all parts'=>'Correggi tutte le parti','Fix Links'=>'Correggi link','Fix Nav'=>'Correggi navigazione','Fix Parts'=>'Correggi parti','Fix Template'=>'Correggi il template','Fixing {n} / {total}…'=>'Correzione di {n} / {total}…','Fixing…'=>'Correzione in corso…','Flush Permalink Rules'=>'Svuota regole permalink','Flush Permalinks'=>'Svuota permalink','Flush Sitemap Cache'=>'Svuota cache Sitemap','Footnote Content'=>'Contenuto della nota a piè di pagina','footnote(s) translated — applied together with content.'=>'Nota a piè di pagina tradotta — applicata insieme al contenuto.','Footnotes'=>'Note a piè di pagina','Footnotes payload (advanced)'=>'Payload delle note a piè di pagina (avanzato)','Forbidden'=>'Vietato','Forced OFF by the LINGUAFORGE_AI_DEBUG constant in wp-config.php. Remove that line to control this toggle from here.'=>'Forzato OFF dalla costante LINGUAFORGE_AI_DEBUG in wp-config.php. Rimuovi quella riga per controllare questa opzione da qui.','Forced ON by the LINGUAFORGE_AI_DEBUG constant in wp-config.php. Remove that line to control this toggle from here.'=>'Forzato ON dalla costante LINGUAFORGE_AI_DEBUG in wp-config.php. Rimuovi quella riga per controllare questa opzione da qui.','Forces the sitemap to regenerate on the next request. Use after bulk-importing or manually editing translation relationships.'=>'Costringe la rigenerazione della sitemap alla prossima richiesta. Usare dopo importazioni di massa o modifica manuale delle relazioni di traduzione.','Found {parts} across <strong>{total}</strong> of <strong>{scanned}</strong> scanned post(s) for <strong>{lang}</strong>.'=>'Trovati {parts} tra <strong>{total}</strong> di <strong>{scanned}</strong> post scansionati per <strong>{lang}</strong>.','From'=>'Da','Front Page'=>'Pagina principale','FSE localisation: scaffold, translate, and fix links in Full Site Editing templates and template parts directly from this tab.'=>'Localizzazione FSE: struttura, traduci e correggi i link nei modelli e nelle parti di modelli di Full Site Editing direttamente da questa scheda.','FSE templates seeded from the active theme. Create then customise in the Site Editor.'=>'Modelli FSE seminati dal tema attivo. Crea e personalizza nel Modificatore del Sito.','Full'=>'Completo','Full Article'=>'Articolo completo','Full post'=>'Post completo','General'=>'Generale','Generate'=>'Genera','Generate Content'=>'Genera contenuto','Generate content…'=>'Genera contenuto…','Generate Excerpt'=>'Genera estratto','Generate Meta Description'=>'Genera meta descrizione','Generate the multilingual sitemap at /lf-sitemap.xml'=>'Genera la sitemap multilingue in /lf-sitemap.xml','Generated Content'=>'Contenuto generato','Generated meta description'=>'Meta descrizione generata','Generating…'=>'Generando…','Generation failed.'=>'Generazione fallita.','Getting started'=>'Iniziare','Global AI preset'=>'Predefinito AI globale','Global default (%s)'=>'Predefinito globale (%s)','Glossary'=>'Glossario','Glossary entry added.'=>'Voce del glossario aggiunta.','Glossary entry removed.'=>'Voce del glossario rimossa.','Glossary Tab'=>'Scheda Glossario','Google (Gemini)'=>'Google (Gemini)','H2-as-H1 mode enabled — title counted as H1 equivalent. (Heading tags could not be detected from the rendered page; verify your theme outputs the title correctly.)'=>'Modalità H2 come H1 attivata — il titolo viene contato come equivalente a H1. (I tag di intestazione potrebbero non essere stati rilevati dalla pagina renderizzata; verifica che il tuo tema produca correttamente il titolo.)','Headings'=>'Intestazioni','Hide'=>'Nascondi','Hints'=>'Suggerimenti','Home link text'=>'Testo del link alla home','How it should appear in the translation. Type the same value as the source term to instruct the AI to preserve it verbatim.'=>'Come dovrebbe apparire nella traduzione. Digita lo stesso valore del termine di origine per istruire l\'IA a conservarlo letteralmente.','How to use'=>'Come usare','Hreflang'=>'Hreflang','Hreflang output'=>'Output hreflang','Hreflang settings saved.'=>'Impostazioni hreflang salvate.','https://github.com/leotiger/lingua-forge'=>'https://github.com/leotiger/lingua-forge','https://lingua-forge.com'=>'https://lingua-forge.com','Icon + label'=>'Icona + etichetta','Icon only'=>'Solo icona','If checked, uninstalling the plugin will permanently delete all language assignments, translation relationships, meta descriptions, per-page presets, the AI glossary, and Translation Memory for every post on this site. This cannot be undone. Leave unchecked unless you are fully removing multilingual support from the site.'=>'Se selezionato, disinstallando il plugin verranno eliminati definitivamente tutte le assegnazioni di lingua, relazioni di traduzione, meta descrizioni, preset per pagina, il glossario AI e la memoria di traduzione per ogni post di questo sito. Questo non può essere annullato. Lasciare deselezionato a meno che non si rimuova completamente il supporto multilingue dal sito.','If you have a general SEO plugin installed, this panel shows how LF adapts to avoid duplicate output. The goal is collision avoidance — not cooperation. LF always provides the multilingual SEO layer (hreflang, og:locale, inLanguage schema) that requires knowledge of LF\'s language routing configuration to produce correctly.'=>'Se hai installato un plugin SEO generale, questo pannello mostra come LF si adatta per evitare output duplicati. L\'obiettivo è evitare collisioni — non cooperare. LF fornisce sempre il livello SEO multilingue (hreflang, og:locale, schema inLanguage) che richiede la conoscenza della configurazione di routing linguistico di LF per essere prodotto correttamente.','If you have Yoast SEO, Rank Math, All in One SEO, or SEOPress installed, Lingua Forge detects them and adapts to avoid duplicate output. For hreflang, LF takes over entirely and suppresses the plugin\'s output because those plugins cannot produce correct hreflang for a multilingual routing configuration. For Open Graph, LF adds only og:locale and og:locale:alternate — the multilingual signals the plugin cannot provide — and leaves the base OG set to the plugin. For Schema.org, LF disables its own output entirely to avoid conflicting JSON-LD graphs.'=>'Se hai installato Yoast SEO, Rank Math, All in One SEO o SEOPress, Lingua Forge li rileva e si adatta per evitare output duplicati. Per hreflang, LF prende il controllo e sopprime l\'output del plugin perché quei plugin non possono produrre hreflang corretto per una configurazione di routing multilingue. Per Open Graph, LF aggiunge solo og:locale e og:locale:alternate — i segnali multilingue che il plugin non può fornire — e lascia il set OG di base al plugin. Per Schema.org, LF disabilita completamente il proprio output per evitare grafici JSON-LD in conflitto.','Images'=>'Immagini','Improve writing'=>'Migliora la scrittura','In the block editor, add a Social Icons block. For each icon, open the link settings and enter one of the "share:" values below as the URL. On the frontend, LF replaces it with the correct share URL for the current page.'=>'Nel editor a blocchi, aggiungi un blocco Icone Social. Per ogni icona, apri le impostazioni del link e inserisci uno dei valori "share:" di seguito come URL. Sul frontend, LF lo sostituisce con l\'URL di condivisione corretto per la pagina corrente.','Includes name, description, inLanguage, url, image, and an Offer with price, priceCurrency, and availability. Price and availability come from the source-language product (shared stock model).'=>'Include nome, descrizione, inLanguage, url, immagine e un\'Offerta con prezzo, valuta del prezzo e disponibilità. Prezzo e disponibilità derivano dal prodotto in lingua originale (modello di stock condiviso).','Includes site name, url, and inLanguage.'=>'Include nome del sito, url e inLanguage.','Informative'=>'Informativo','Input tokens'=>'Token di input','Install'=>'Installa','Install a Language'=>'Installa una lingua','Installed SEO plugins'=>'Plugin SEO installati','Installing…'=>'Installazione…','instock / oos / pending from WC stock status'=>'in stock / oos / pending dallo stato di stock di WC','Instructions (optional)'=>'Istruzioni (opzionale)','Instructions / key points'=>'Istruzioni / punti chiave','Integration API'=>'API di integrazione','Internal Link Fixer'=>'Correttore link interno','Introduction only'=>'Solo introduzione','Invalid file reference.'=>'Riferimento al file non valido.','Invalid filename.'=>'Nome file non valido.','Invalid language code.'=>'Codice lingua non valido.','Invalid language.'=>'Lingua non valida.','Invalid locale code.'=>'Codice locale non valido.','Invalid or primary language.'=>'Lingua non valida o primaria.','Invalid post ID.'=>'ID post non valido.','Invalid post type.'=>'Tipo di post non valido.','Invalid template part.'=>'Parte del modello non valida.','Invalid template type.'=>'Tipo di modello non valido.','JavaScript-powered actions'=>'Azioni alimentate da JavaScript','Just now'=>'Proprio ora','Key points, ideas, or structure to build from…'=>'Punti chiave, idee o struttura da cui partire…','Keys are encrypted with AES-256-CBC before being stored in the WordPress database. The encryption secret is derived from your WordPress auth salts (wp-config.php), so plaintext keys never touch the database.'=>'Le chiavi sono criptate con AES-256-CBC prima di essere memorizzate nel database di WordPress. Il segreto di crittografia deriva dai sali di autenticazione di WordPress (wp-config.php), quindi le chiavi in testo semplice non vengono mai toccate dal database.','Landing / Short-form'=>'Landing / Forma breve','Language'=>'Lingua','Language %s installed successfully.'=>'Lingua %s installata con successo.','Language (optional)'=>'Lingua (opzionale)','Language installation is disabled on this server (DISALLOW_FILE_MODS is set).'=>'L\'installazione della lingua è disabilitata su questo server (DISALLOW_FILE_MODS è impostato).','Language installation is disabled on this server. The DISALLOW_FILE_MODS constant is set in wp-config.php. Install language packs manually via WP-CLI: wp language core install de_DE'=>'L\'installazione del pacchetto di lingua è disabilitata su questo server. La costante DISALLOW_FILE_MODS è impostata in wp-config.php. Installa manualmente i pacchetti di lingua tramite WP-CLI: wp language core install de_DE','Language label'=>'Etichetta lingua','Language Overrides'=>'Sovrascritture della lingua','Language Overrides: manage custom .po/.mo override files for the Lingua Forge UI strings. Use this instead of editing plugin files directly — overrides survive updates.'=>'Override di lingua: gestisci i file di override personalizzati .po/.mo per le stringhe dell\'interfaccia Lingua Forge. Usa questo invece di modificare direttamente i file del plugin — le override sopravvivono agli aggiornamenti.','Language pack installation failed. The language may already be installed, the locale code may be incorrect, or your server may block file writes.'=>'Installazione del pacchetto di lingua fallita. La lingua potrebbe essere già installata, il codice locale potrebbe essere errato, o il server potrebbe bloccare le scritture sui file.','Language Setup'=>'Configurazione della lingua','Language Switcher'=>'Selettore lingua','Language switcher'=>'Switcher di lingua','Language uninstalled. %d post deleted.'=>'Lingua disinstallata. %d post eliminati.' . "\0" . 'Lingua disinstallata. %d post eliminati.','Language-specific copies of the theme\'s template parts. Once scaffolded, templates are updated to reference the language-specific part.'=>'Copie specifiche della lingua delle parti del modello del tema. Una volta create, i modelli vengono aggiornati per fare riferimento alla parte specifica della lingua.','Language:'=>'Lingua:','Languages currently known to the router (derived from installed WordPress locale packs plus the primary language). Install additional language packs in the section below to make more languages available for routing and translation.'=>'Lingue attualmente conosciute dal router (derivate dai pacchetti di localizzazione di WordPress installati più la lingua principale). Installa pacchetti di lingua aggiuntivi nella sezione sottostante per rendere disponibili più lingue per il routing e la traduzione.','Last 30 days'=>'Ultimi 30 giorni','Last 7 days'=>'Ultimi 7 giorni','Last generated: %s'=>'Ultima generazione: %s','Last rule-based SEO score. Run analysis in Settings → SEO → Analysis to update.'=>'Ultimo punteggio SEO basato su regole. Esegui analisi in Impostazioni → SEO → Analisi per aggiornare.','Last run: %s ago'=>'Ultima esecuzione: %s fa','Lead paragraph (≤60 w)'=>'Paragrafo introduttivo (≤60 parole)','Leave a model field blank to use the built-in default for that tier. The placeholder text shows which model will be used.'=>'Lascia un campo modello vuoto per usare il predefinito integrato per quel livello. Il testo segnaposto mostra quale modello verrà usato.','Leave blank for brand names and language-agnostic terms that should be enforced regardless of which language we are translating from.'=>'Lascia vuoto per nomi di marca e termini indipendenti dalla lingua che devono essere mantenuti invariati indipendentemente dalla lingua di origine.','Leave blank to apply this entry to all target languages — ideal for brand names, abbreviations, and terms that must be preserved verbatim in every translation.'=>'Lascia vuoto per applicare questa voce a tutte le lingue di destinazione — ideale per nomi di marca, abbreviazioni e termini che devono essere preservati letteralmente in ogni traduzione.','Leave blank to keep the existing key. Enter a new value to replace it.'=>'Lascia vuoto per mantenere la chiave esistente. Inserisci un nuovo valore per sostituirla.','Leave blank to use the built-in default. Clearing a saved override restores the default on next save.'=>'Lascia vuoto per usare il valore predefinito integrato. Cancellare una sovrascrittura salvata ripristina il default al prossimo salvataggio.','Legacy lf-social-share mu-plugin'=>'Legacy lf-social-share mu-plugin','Legacy lf-social-share mu-plugin detected. LF is deferring the base OG set to the mu-plugin and outputting og:locale + og:locale:alternate only. You can deactivate the mu-plugin — LF\'s built-in Social Share (SEO → Social Share tab) and Open Graph cover the same functionality.'=>'Rilevato legacy lf-social-share mu-plugin. LF deferisce l\'insieme OG di base al mu-plugin e produce solo og:locale + og:locale:alternate. Puoi disattivare il mu-plugin — LF\'s built-in Social Share (scheda SEO → Social Share) e Open Graph coprono la stessa funzionalità.','Legal / Compliance'=>'Legale / Conformità','Legal / Compliance instructions'=>'Istruzioni legali / di conformità','LF always adds og:locale and og:locale:alternate — the multilingual OG signals no general SEO plugin can produce correctly. For the base OG set (og:title, og:description, og:image), LF outputs it when no other plugin is present. When a SEO plugin is installed, LF skips the base set to avoid duplicate tags — not because the plugin is "better", but because duplication produces no value.'=>'LF aggiunge sempre og:locale e og:locale:alternate — i segnali multilingue che nessun plugin SEO può produrre correttamente. Per il set OG di base (og:title, og:description, og:image), LF lo produce quando nessun altro plugin è presente. Quando è installato un plugin SEO, LF salta il set di base per evitare tag duplicati — non perché il plugin sia "migliore", ma perché la duplicazione non ha valore.','LF generates its own sitemap with xhtml:link alternates for all translation groups. When a SEO plugin is installed, it generates a separate sitemap — both coexist independently. Submit both to Google Search Console: the SEO plugin sitemap for content discovery, the LF sitemap for language relationship signals.'=>'LF genera la propria sitemap con alternates xhtml:link per tutti i gruppi di traduzione. Quando è installato un plugin SEO, ne genera una separata — coesistono indipendentemente. Invia entrambe a Google Search Console: la sitemap del plugin SEO per la scoperta dei contenuti, la sitemap di LF per i segnali di relazione linguistica.','LF is outputting hreflang tags and has removed the WordPress core canonical tag on multilingual pages.'=>'LF sta producendo tag hreflang e ha rimosso il tag canonico di WordPress sui pagine multilingue.','LF is suppressing hreflang output from: %s'=>'LF sta sopprimendo l\'output hreflang da: %s','LF outputs accurate hreflang for every configured language, including x-default. General SEO plugins have no access to your LF routing configuration and would produce hreflang based on incorrect URL assumptions. LF suppresses their output via filter to prevent collisions.'=>'LF fornisce hreflang accurati per ogni lingua configurata, incluso x-default. I plugin SEO generali non hanno accesso alla configurazione di routing di LF e producono hreflang basati su supposizioni errate sugli URL. LF sopprime la loro uscita tramite filtro per prevenire collisioni.','LF outputs multilingual JSON-LD with inLanguage annotations tied to its language routing configuration. When a SEO plugin is installed, LF disables its own schema entirely: duplicate JSON-LD graphs produce validation errors and there is no clean way to supplement an existing graph.'=>'LF produce JSON-LD multilingue con annotazioni inLanguage collegate alla sua configurazione di routing linguistico. Quando viene installato un plugin SEO, LF disabilita completamente il proprio schema: grafici JSON-LD duplicati generano errori di convalida e non c\'è modo semplice di integrare un grafico esistente.','LF provides'=>'LF fornisce','LF removes the WordPress core canonical tag on multilingual pages because the router\'s language-prefixed rewrite rules and the hreflang x-default are the correct canonical signals for a multilingual site. This prevents a double-canonical if a SEO plugin also outputs one. LF does not add its own canonical — the language routing already makes each URL canonical.'=>'LF rimuove il tag canonico di WordPress sui pagine multilingue perché le regole di riscrittura con prefisso di lingua del router e l\'hreflang x-default sono i segnali canonici corretti per un sito multilingue. Questo previene un doppio canonico se anche un plugin SEO ne genera uno. LF non aggiunge il proprio canonico — la routing linguistica rende già ogni URL canonico.','LF-owned entries currently registered in $wp_rewrite->extra_rules_top. Useful for diagnosing 404s or routing conflicts. Copy these when filing a bug report.'=>'Voci di proprietà LF attualmente registrate in $wp_rewrite->extra_rules_top. Utile per diagnosticare 404 o conflitti di routing. Copia queste quando segnali un bug.','Light'=>'Leggero','Light (default — fast and cost-effective)'=>'Leggero (predefinito — rapido ed economico)','Light (fast and cost-effective — Haiku / Flash)'=>'Leggero (veloce ed economico — Haiku / Flash)','Light model'=>'Modello leggero','Light: used for meta descriptions and excerpt generation — fast, low cost.'=>'Leggero: usato per le meta descrizioni e la generazione di estratti — veloce, a basso costo.','Limit results to pages in the given Lingua Forge language code.'=>'Limita i risultati alle pagine nella lingua di Lingua Forge specificata.','Limits'=>'Limiti','Lingua Forge'=>'Lingua Forge','Lingua Forge adds multilingual routing, AI-powered translation, hreflang SEO tags, and a language switcher to your WordPress site.'=>'Lingua Forge aggiunge routing multilingue, traduzione alimentata da AI, tag SEO hreflang e un switcher di lingua al tuo sito WordPress.','Lingua Forge adds WooCommerce-specific Open Graph properties to product pages so that sharing a product URL on Facebook, Pinterest, and similar platforms surfaces the correct product type, price, and availability.'=>'Lingua Forge aggiunge proprietà Open Graph specifiche di WooCommerce alle pagine prodotto in modo che la condivisione di un URL di prodotto su Facebook, Pinterest e piattaforme simili mostri il tipo di prodotto, il prezzo e la disponibilità corretti.','Lingua Forge AI Tools'=>'Strumenti AI di Lingua Forge','Lingua Forge extends the WordPress Core Social Icons block with dynamic share URLs. Set any icon\'s link to a "share:" value and LF rewrites it to the correct share URL or JavaScript action at render time — no custom code or third-party plugin required.'=>'Lingua Forge estende il blocco Icone Social di WordPress Core con URL di condivisione dinamici. Imposta il link di qualsiasi icona su un valore "share:" e LF lo riscrive con l\'URL di condivisione corretto o l\'azione JavaScript al momento del rendering — nessun codice personalizzato o plugin di terze parti richiesto.','Lingua Forge generates a dedicated XML sitemap at /lf-sitemap.xml that adds language alternate links for all your translated content. This sitemap complements the WordPress core sitemap and any SEO plugin sitemap — it does not replace them.'=>'Lingua Forge genera una sitemap XML dedicata su /lf-sitemap.xml che aggiunge link alternativi di lingua per tutti i tuoi contenuti tradotti. Questa sitemap integra la sitemap di WordPress e quella di qualsiasi plugin SEO — non le sostituisce.','Lingua Forge is a complete multilingual SEO solution. No additional SEO plugin is required.'=>'Lingua Forge è una soluzione SEO multilingue completa. Non è richiesto alcun plugin SEO aggiuntivo.','Lingua Forge is a complete multilingual SEO solution. No additional SEO plugin or sitemap plugin is required.'=>'Lingua Forge è una soluzione SEO multilingue completa. Non è richiesto alcun plugin SEO o sitemap aggiuntivo.','Lingua Forge outputs <link rel="alternate" hreflang> tags for every configured language on every page, including x-default pointing to the source language. This is the primary multilingual SEO signal for Google and other search engines — no additional SEO plugin is required.'=>'Lingua Forge genera tag <link rel="alternate" hreflang> per ogni lingua configurata su ogni pagina, incluso x-default che punta alla lingua di origine. Questo è il principale segnale SEO multilingue per Google e altri motori di ricerca — non è necessario alcun plugin SEO aggiuntivo.','Lingua Forge outputs Open Graph and Twitter Card meta tags so shared URLs display the correct language, title, description, and image on social platforms.'=>'Lingua Forge produce meta tag Open Graph e Twitter Card in modo che gli URL condivisi mostrino la lingua, il titolo, la descrizione e l\'immagine corretti sui social.','Lingua Forge outputs Schema.org JSON-LD structured data so search engines understand your content type, language, and metadata. This is the primary way to communicate inLanguage annotations for multilingual content to Google and other crawlers.'=>'Lingua Forge produce dati strutturati JSON-LD Schema.org in modo che i motori di ricerca comprendano il tipo di contenuto, la lingua e i metadati. Questo è il modo principale per comunicare annotazioni inLanguage per contenuti multilingue a Google e altri crawler.','Lingua Forge restricts two Gutenberg features by default to keep editorial behavior consistent across languages. Opt in here when you need full Gutenberg / FSE capabilities.'=>'Lingua Forge limita di default due funzionalità di Gutenberg per mantenere coerente il comportamento editoriale tra le lingue. Attiva qui se hai bisogno di tutte le capacità di Gutenberg / FSE.','Lingua Forge Settings'=>'Impostazioni Lingua Forge','Lingua Forge uses two independent caching layers to avoid redundant AI API calls. Use the tabs below to inspect and manage each one.'=>'Lingua Forge utilizza due livelli di cache indipendenti per evitare chiamate API AI ridondanti. Usa le schede sottostanti per ispezionare e gestire ciascuna.','Lingua Forge uses two model tiers per provider:'=>'Lingua Forge utilizza due livelli di modelli per provider:','Lingua Forge version'=>'Versione Lingua Forge','Lingua Forge — Quick Translate'=>'Lingua Forge — Traduzione rapida','Lingua Forge — Settings'=>'Lingua Forge — Impostazioni','Lingua Forge\'s built-in Social Share and Open Graph modules cover all functionality the mu-plugin provides, plus multilingual og:locale support. You can safely deactivate the mu-plugin.'=>'I moduli integrati di Social Share e Open Graph di Lingua Forge coprono tutte le funzionalità fornite dal mu-plugin, più il supporto multilingue og:locale. Puoi disattivare in sicurezza il mu-plugin.','Link copied'=>'Link copiato','link(s)'=>'link(i)','Links'=>'Link','Load available languages'=>'Carica le lingue disponibili','Load content'=>'Carica contenuto','Loaded from cache.'=>'Caricato dalla cache.','Loading…'=>'Caricamento…','Locale only'=>'Solo località','Locked — a conflicting SEO plugin is active. See the notice above.'=>'Bloccato — è attivo un plugin SEO in conflitto. Vedi l\'avviso sopra.','Loco Translate stores its custom translations in wp-content/languages/loco/ — a location that can be silently wiped by a WP core update, plugin reinstall, or if Loco Translate itself is removed. Copying files here moves them into the Lingua Forge i18n-overrides directory, which persists through all of those events and is loaded automatically on every request.'=>'Loco Translate memorizza le sue traduzioni personalizzate in wp-content/languages/loco/ — una posizione che può essere cancellata silenziosamente da un aggiornamento di WP core, reinstallazione del plugin, o se Loco Translate viene rimosso. Copiare i file qui li sposta nella directory Lingua Forge i18n-overrides, che persiste attraverso tutti questi eventi ed è caricata automaticamente ad ogni richiesta.','Loco Translate — Copy to Safe Storage'=>'Loco Translate — Copia in Archiviazione Sicura','Lowest WordPress capability allowed to trigger AI features. Tightening this on multi-author sites prevents Contributors or trial accounts from running paid AI calls. Override per-feature via the linguaforge_required_capability filter.'=>'La capacità di WordPress più bassa consentita per attivare le funzioni IA. Ristretta su siti multi-autore per impedire a Contributori o account di prova di eseguire chiamate IA a pagamento. Sovrascrivi per funzione tramite il filtro linguaforge_required_capability.','Maintenance'=>'Manutenzione','Maintenance Tab'=>'Scheda Manutenzione','Make casual'=>'Rendi informale','Make concise'=>'Rendi conciso','Make formal'=>'Rendi formale','Mark citations needed'=>'Segna le citazioni necessarie','Max context characters'=>'Caratteri di contesto massimi','Max hints characters'=>'Caratteri massimi per suggerimenti','Max input characters'=>'Caratteri di input massimi','Max output tokens'=>'Token di output massimo','Maximum characters accepted from the input field. Default: 8 000.'=>'Caratteri massimi accettati dal campo di input. Predefinito: 8.000.','Maximum characters of existing post content passed to the AI as seed context when no Hints are provided. Default: 6 000.'=>'Caratteri massimi del contenuto del post esistente passati all\'IA come contesto seme quando non vengono forniti Suggerimenti. Predefinito: 6.000.','Maximum characters read from the Hints field. Default: 2 000.'=>'Caratteri massimi letti dal campo Suggerimenti. Predefinito: 2.000.','Maximum number of characters of post content forwarded to the AI. 0 means no limit — the full content is always sent (recommended). Set a non-zero value only if your provider has a tight context window. A warning is written to the PHP error log whenever the content is trimmed.'=>'Numero massimo di caratteri del contenuto del post inoltrato all\'IA. 0 significa nessun limite — il contenuto completo viene sempre inviato (consigliato). Imposta un valore diverso da zero solo se il tuo provider ha una finestra di contesto ristretta. Viene scritto un avviso nel registro degli errori PHP ogni volta che il contenuto viene troncato.','Maximum number of tokens the AI may produce in a single translation response. If a translation is silently cut off at the end, increase this value. Default: 16 000.'=>'Numero massimo di token che l\'IA può produrre in una singola risposta di traduzione. Se una traduzione viene tagliata silenziosamente alla fine, aumenta questo valore. Predefinito: 16.000.','Maximum tokens the AI may produce per generation run. Raise this if full articles are being cut off. Default: 8 192.'=>'Token massimi che l\'IA può produrre per ogni esecuzione di generazione. Aumenta questo limite se gli articoli completi vengono tagliati. Predefinito: 8.192.','Maximum tokens the AI may produce per quick translation. Default: 2 000.'=>'Token massimi che l\'IA può produrre per ogni traduzione rapida. Predefinito: 2.000.','Meta Description'=>'Meta descrizione','Meta description'=>'Meta descrizione','Meta Description, Excerpt Generator'=>'Meta Descrizione, Generatore di estratti','Metric'=>'Metri','Minimum role'=>'Ruolo minimo','Missing'=>'Mancante','Missing pattern name or language.'=>'Nome del pattern o lingua mancanti.','Mode'=>'Modo','Model'=>'Modello','Model tier'=>'Livello del modello','Models'=>'Modelli','Models Tab (General)'=>'Scheda Modelli (Generale)','Modified'=>'Modificato','Most recent cached block'=>'Blocco memorizzato più recente','Most recent cached response'=>'Risposta memorizzata più recente','Multilingual routing, complete multilingual SEO (hreflang, Open Graph, Schema.org, sitemap), and AI content tools for WordPress. Language detection, URL routing, translation, content generation, and a full SEO layer — no companion plugin required.'=>'Routing multilingue, SEO multilingue completo (hreflang, Open Graph, Schema.org, sitemap), e strumenti di contenuto AI per WordPress. Rilevamento della lingua, routing URL, traduzione, generazione di contenuti e un livello SEO completo — nessun plugin companion richiesto.','Multilingual SEO'=>'SEO multilingue','Multilingual SEO overview'=>'Panoramica SEO multilingue','My Account'=>'Il mio account','Name displayed in this language. Leave empty to use the source name.'=>'Nome visualizzato in questa lingua. Lascia vuoto per usare il nome originale.','Navigation'=>'Navigazione','Navigation has no content to translate.'=>'La navigazione non ha contenuto da tradurre.','Navigation not found.'=>'Navigazione non trovata.','Navigation posts are translated via the Router tab, not this button.'=>'I post di navigazione vengono tradotti tramite la scheda Router, non con questo pulsante.','Navigation translation requires an active AI provider. Configure an API key in the API Keys tab.'=>'La traduzione della navigazione richiede un provider AI attivo. Configura una chiave API nella scheda Chiavi API.','Navigations'=>'Navigazioni','Network error — could not reach the WordPress AJAX endpoint.'=>'Errore di rete — impossibile raggiungere il punto finale AJAX di WordPress.','Network error.'=>'Errore di rete.','Never run'=>'Mai eseguire','No %s version found in this translation group.'=>'Nessuna versione %s trovata in questo gruppo di traduzioni.','No action needed. Google deprecated its sitemap ping endpoint in January 2024 and now discovers sitemaps exclusively via the robots.txt Sitemap: directive — which LF has already configured. Google will pick it up on its next crawl.'=>'Nessuna azione necessaria. Google ha deprecato il suo endpoint di ping sitemap a gennaio 2024 e ora scopre le sitemap esclusivamente tramite la direttiva Sitemap nel robots.txt — che LF ha già configurato. Google la rileverà al prossimo crawling.','No AI provider configured.'=>'Nessun provider AI configurato.','No AI provider configured. Add an API key in Settings → API Keys.'=>'Nessun provider AI configurato. Aggiungi una chiave API in Impostazioni → Chiavi API.','No AI usage recorded in the selected window (%s). Pick a wider range above.'=>'Nessun utilizzo di AI registrato nella finestra selezionata (%s). Scegli un intervallo più ampio sopra.','No AI usage recorded yet. Once an editor runs a translation, generates a meta description, or uses any other AI feature, totals will appear here.'=>'Nessun utilizzo di AI registrato finora. Una volta che un editor esegue una traduzione, genera una meta descrizione o utilizza qualsiasi altra funzionalità AI, i totali appariranno qui.','No API key configured for this provider.'=>'Nessuna chiave API configurata per questo provider.','No built-in instructions — each AI feature uses its own tuned defaults. Fill in the Custom prompt instructions field below to add your own site-wide rules.'=>'Nessuna istruzione predefinita — ogni funzione AI utilizza le proprie impostazioni di default ottimizzate. Compila il campo Istruzioni prompt personalizzate qui sotto per aggiungere le tue regole a livello di sito.','No conflicting SEO plugins detected. Lingua Forge is handling all SEO output independently.'=>'Nessun plugin SEO in conflitto rilevato. Lingua Forge gestisce tutto l\'output SEO in modo indipendente.','No custom Loco Translate files found yet. They appear here once you save a translation in Loco Translate.'=>'Ancora nessun file personalizzato di Loco Translate trovato. Appaiono qui una volta che salvi una traduzione in Loco Translate.','No external OG plugin detected. LF is outputting the full OG + Twitter Card set.'=>'Nessun plugin OG esterno rilevato. LF produce l\'intero set OG + Twitter Card.','No file was selected.'=>'Nessun file selezionato.','No glossary entries match the current filter. Clear the filter to see all entries, or add a new entry below.'=>'Nessuna voce del glossario corrisponde al filtro attuale. Rimuovi il filtro per visualizzare tutte le voci o aggiungi una nuova voce qui sotto.','No glossary entries yet. Add one below to start enforcing terminology in translations.'=>'Ancora nessuna voce del glossario. Aggiungine una sotto per iniziare a applicare la terminologia nelle traduzioni.','No H1 found. Typically the post title is the H1 — verify your theme is outputting it.'=>'Nessun H1 trovato. Tipicamente il titolo del post è l\'H1 — verifica che il tuo tema lo produca.','No images found in content.'=>'Nessuna immagine trovata nel contenuto.','No internal links found to update.'=>'Nessun collegamento interno trovato da aggiornare.','No language-specific template parts found to map.'=>'Nessuna parte del modello specifica della lingua trovata da mappare.','No LF meta description set — using excerpt/content.'=>'Nessuna meta descrizione LF impostata — si utilizza l\'estratto/contenuto.','No LF rewrite rules found. Flush permalinks if this is unexpected.'=>'Nessuna regola di riscrittura LF trovata. Svuota i permalink se questo è inaspettato.','No links found.'=>'Nessun link trovato.','No links found. Internal links improve crawlability and user navigation.'=>'Nessun link trovato. I link interni migliorano la navigazione e la crawlabilità.','No meta description found. Generate one via the AI meta description feature.'=>'Nessuna meta descrizione trovata. Genera una tramite la funzione di meta descrizione AI.','No navigation references needed updating.'=>'Nessun riferimento di navigazione da aggiornare.','No override files uploaded yet.'=>'Nessun file di sovrascrittura ancora caricato.','No physical robots.txt file found. WordPress is generating it virtually and LF\'s Sitemap directive is included automatically.'=>'Nessun file robots.txt fisico trovato. WordPress lo genera virtualmente e la direttiva Sitemap di LF è inclusa automaticamente.','No published posts found for the selected filters.'=>'Nessun post pubblicato trovato per i filtri selezionati.','No response from AI provider. Check your API key and try again.'=>'Nessuna risposta dal provider AI. Controlla la tua chiave API e riprova.','No response from provider — check the error log for details.'=>'Nessuna risposta dal provider — controlla il registro degli errori per i dettagli.','No secondary languages configured.'=>'Nessuna lingua secondaria configurata.','No secondary languages configured. Install a language pack above to enable template scaffolding.'=>'Nessuna lingua secondaria configurata. Installa un pacchetto di lingua sopra per abilitare lo scaffolding del modello.','No source content found to translate.'=>'Nessun contenuto di origine trovato da tradurre.','No source page linked yet.'=>'Ancora nessuna pagina di origine collegata.','No template part references needed updating.'=>'Nessun riferimento alla parte del modello da aggiornare.','No third-party SEO plugins detected. Lingua Forge handles all multilingual SEO output.'=>'Nessun plugin SEO di terze parti rilevato. Lingua Forge gestisce tutta la SEO multilingue.','No title set.'=>'Nessun titolo impostato.','No translated content found. The sitemap will populate once posts have been translated.'=>'Nessun contenuto tradotto trovato. La sitemap si popolerà una volta tradotti i post.','No translation found — analyzed the source language version.'=>'Nessuna traduzione trovata — analizzata la versione in lingua originale.','No {lang} translation registered (TRID missing)'=>'Nessuna traduzione {lang} registrata (TRID mancante)','No — WooCommerce integration class not loaded'=>'Nessuna classe di integrazione WooCommerce caricata','Not set — AI features are disabled.'=>'Non impostato — le funzionalità AI sono disabilitate.','Not yet generated. The sitemap is built on the first visit to the sitemap URL and cached for 24 hours.'=>'Non ancora generata. La sitemap viene creata alla prima visita all\'URL della sitemap e memorizzata nella cache per 24 ore.','Notes'=>'Note','Nothing — all types disabled'=>'Niente — tutti i tipi disattivati','Notice message'=>'Messaggio di notifica','Notice settings'=>'Impostazioni di notifica','Notify search engines'=>'Notifica ai motori di ricerca','Numeric permalink structure is not supported.'=>'La struttura permalink numerica non è supportata.','OG/Twitter Card tags: handled by LF\'s Open Graph module (SEO → Open Graph & Twitter Cards)'=>'Tag OG/Twitter Card: gestiti dal modulo Open Graph di LF (SEO → Open Graph & Twitter Cards)','Oldest cached block'=>'Blocco più vecchio memorizzato','Oldest cached response'=>'Risposta più vecchia memorizzata','Only .mo files are accepted.'=>'Sono accettati solo file .mo.','Open Graph'=>'Open Graph','Open Graph &amp; Twitter Cards'=>'Open Graph &amp; Twitter Cards','Open Graph output'=>'Uscita Open Graph','Open Graph settings saved.'=>'Impostazioni Open Graph salvate.','Open Search Console →'=>'Apri Search Console →','Open the browser\'s native Web Share sheet (iOS, Android, some desktops). Falls back to clipboard copy if not supported.'=>'Apri il foglio di condivisione Web nativo del browser (iOS, Android, alcuni desktop). Ritorna alla copia negli appunti se non supportato.','OpenAI (GPT)'=>'OpenAI (GPT)','Optional context for editors (e.g. "ASIC = Application-Specific Integrated Circuit; preserve in English in technical contexts").'=>'Contesto opzionale per gli editor (ad esempio "ASIC = Circuito integrato specifico per applicazione; da conservare in inglese in contesti tecnici").','Optional. Bing already reads the Sitemap: directive from robots.txt — this just triggers an immediate recrawl instead of waiting for the next scheduled check.'=>'Opzionale. Bing già legge la direttiva Sitemap: da robots.txt — questo attiva una ricraw immediata invece di aspettare il prossimo controllo programmato.','Optional. Yandex already reads the Sitemap: directive from robots.txt — this just triggers an immediate recrawl instead of waiting for the next scheduled check.'=>'Opzionale. Yandex già legge la direttiva Sitemap: da robots.txt — questo attiva una ricraw immediata invece di aspettare il prossimo controllo programmato.','Output'=>'Output','Output Article or WebPage schema on singular posts and pages'=>'Produci schema Article o WebPage su post e pagine singole','Output hreflang tags in wp_head'=>'Produci tag hreflang in wp_head','Output mode'=>'Modalità di output','Output Open Graph tags in wp_head'=>'Produci tag Open Graph in wp_head','Output Product schema on WooCommerce product pages'=>'Produci schema Product sulle pagine prodotto di WooCommerce','Output Schema.org JSON-LD in wp_head'=>'Schema.org JSON-LD in output in wp_head','Output tokens'=>'Token di output','Output WebSite schema on the front page and blog index'=>'Schema del sito web in homepage e indice del blog','Overall SEO score'=>'Punteggio SEO complessivo','overridden'=>'sovrascritto','Override file deleted.'=>'File di sovrascrittura eliminato.','Override file uploaded successfully.'=>'File di sovrascrittura caricato con successo.','Overrides the AI preset for Translation and Content Generation on this page. All other features always use the global preset.'=>'Sovrascrive il preset AI per Traduzione e Generazione di contenuti su questa pagina. Tutte le altre funzionalità usano sempre il preset globale.','Overrides the AI preset for Translation and Content Generation on this page. Site-wide custom prompt instructions (Settings → Behavior) are always appended to every request regardless of this selection.'=>' Sovrascrive il preset AI per Traduzione e Generazione di contenuti su questa pagina. Le istruzioni personalizzate a livello di sito (Impostazioni → Comportamento) vengono sempre aggiunte a ogni richiesta indipendentemente da questa selezione.','Overview'=>'Panoramica','Page'=>'Pagina','Part'=>'Parte','Paste a footnote, sentence, or any snippet here…'=>'Incolla una nota a piè di pagina, una frase o qualsiasi frammento qui…','Paste text, or select text in the editor first…'=>'Incolla il testo, o seleziona prima il testo nell\'editor…','Paste text, or select text on the page first…'=>'Incolla il testo, o seleziona prima il testo sulla pagina…','Paste your API key…'=>'Incolla la tua chiave API…','Path prefix (/de/)'=>'Prefisso del percorso (/de/)','Path prefix — example.com/de/'=>'Prefisso del percorso — example.com/it/','Path routing requires a post-name based permalink structure. Change it in'=>'Il routing del percorso richiede una struttura permalink basata sul nome del post. Modificalo in','Pattern'=>'Modello','Pattern has no content to translate.'=>'Il pattern non ha contenuto da tradurre.','Pattern not found.'=>'Pattern non trovato.','Pattern translated and saved. Copy the content into your CPT post via the block editor Pattern inserter or use it as a starting point for a Reusable Block.'=>'Pattern tradotto e salvato. Copia il contenuto nel tuo post CPT tramite l\'inseritore di pattern dell\'editor a blocchi o usalo come punto di partenza per un blocco riutilizzabile.','Pattern translation failed.'=>'Fallimento della traduzione del modello.','Per-Post Analysis'=>'Analisi per post','Per-post cache for AI-generated translations, meta descriptions, excerpts, and content. Entries are invalidated automatically when the content or AI provider/model changes.'=>'Cache per ogni post per traduzioni generate dall\'IA, meta descrizioni, estratti e contenuti. Le voci vengono invalidata automaticamente quando il contenuto o il provider/modello AI cambiano.','Permalink rules flushed successfully.'=>'Regole permalink svuotate con successo.','Permalink Structure'=>'Struttura permalink','Permalink structure is compatible with Lingua Forge path routing.'=>'La struttura permalink è compatibile con il routing del percorso di Lingua Forge.','Permanently deletes all templates, template parts, patterns, navigation menus, posts, pages, custom post types, products, and product variations associated with this language. Also removes the WordPress locale pack files so this language no longer appears in the router. This action cannot be undone.'=>'Elimina definitivamente tutti i modelli, parti di modelli, pattern, menu di navigazione, post, pagine, tipi di post personalizzati, prodotti e variazioni di prodotto associate a questa lingua. Rimuove anche i file del pacchetto locale di WordPress in modo che questa lingua non appaia più nel router. Questa azione non può essere annullata.','Permanently uninstall %s? This will delete all translated content for this language and cannot be undone.'=>'Disinstallare definitivamente %s? Questo eliminerà tutto il contenuto tradotto per questa lingua e non può essere annullato.','Permission denied.'=>'Permesso negato.','Persuasive'=>'Persuasivo','PHP constant'=>'costante PHP','PHP max_execution_time'=>'Tempo massimo di esecuzione PHP','PHP memory_limit'=>'Limite di memoria PHP','PHP version'=>'Versione PHP','Pin on Pinterest'=>'Pin su Pinterest','Pin terms that must not be translated or must always be rendered in a specific way (e.g. brand names, product names, acronyms). Glossary constraints are injected into every AI translation request for all features: post translation, meta description, excerpt, and FSE template translation.'=>'Blocca i termini che non devono essere tradotti o devono sempre essere resi in modo specifico (ad esempio nomi di marca, nomi di prodotto, acronimi). Le restrizioni del glossario vengono inserite in ogni richiesta di traduzione AI per tutte le funzionalità: traduzione del post, meta descrizione, estratto e traduzione del modello FSE.','Ping Bing'=>'Ping Bing','Ping Yandex'=>'Ping Yandex','Plain language'=>'Linguaggio semplice','Plain permalinks are not supported.'=>'Permalink semplici non sono supportati.','Please enter some instructions first…'=>'Per favore inserisci prima delle istruzioni…','Please enter some text first…'=>'Per favore inserisci del testo prima…','Plugin'=>'Plugin','Post'=>'Post','Post not found or not published.'=>'Post non trovato o non pubblicato.','Post not found.'=>'Post non trovato.','Post on X / Twitter'=>'Post su X / Twitter','Post type'=>'Tipo di post','Post Types'=>'Tipi di post','Posts without _lf_lang are invisible to every Lingua Forge language filter. This can happen when content is imported or created before the plugin was activated.'=>'I post senza _lf_lang sono invisibili a ogni filtro di lingua di Lingua Forge. Questo può accadere quando il contenuto viene importato o creato prima dell\'attivazione del plugin.','Prefilled from excerpt. Edit to override.'=>'Precompilata dall\'estratto. Modifica per sovrascrivere.','Price and availability always reflect the source-language product (shared stock model). Tags are only output when LF\'s Open Graph module is set to "Full" or "Auto" mode with no conflicting SEO plugin detected.'=>'Prezzo e disponibilità riflettono sempre il prodotto in lingua originale (modello di stock condiviso). I tag vengono visualizzati solo quando il modulo Open Graph di LF è impostato su "Completo" o "Auto" senza plugin SEO in conflitto rilevato.','Primary Language'=>'Lingua principale','Primary language'=>'Lingua principale','Primary language saved.'=>'Lingua principale salvata.','Primary language: the language your existing content is written in. All translations are produced from this language; changing it does not move or delete any posts.'=>'Lingua principale: la lingua in cui è scritto il tuo contenuto esistente. Tutte le traduzioni sono prodotte da questa lingua; cambiarla non sposta né elimina alcun post.','Processing…'=>'Elaborazione…','Product'=>'Prodotto','Product / eCommerce'=>'Prodotto / eCommerce','Product Open Graph'=>'Open Graph del prodotto','Product — WooCommerce product pages'=>'Prodotto — pagine prodotto WooCommerce','Profile'=>'Profilo','Provider'=>'Provider','Provider returned no text. Check the WordPress error log for the detailed failure reason.'=>'Il provider non ha restituito testo. Controlla il registro errori di WordPress per il motivo dettagliato del fallimento.','Quality'=>'Qualità','Quality (default — Sonnet / GPT-4o / Gemini Pro)'=>'Qualità (predefinito — Sonnet / GPT-4o / Gemini Pro)','Quality (Sonnet / GPT-4o / Gemini Pro)'=>'Qualità (Sonnet / GPT-4o / Gemini Pro)','Quality model'=>'Modello di qualità','Quality: used for post translation and content generation — higher quality, higher cost.'=>'Qualità: usata per la traduzione dei post e la generazione di contenuti — qualità superiore, costo superiore.','Quick Translate'=>'Traduzione rapida','Quick Translation'=>'Traduzione rapida','Quick Translation is used for snippet/chunk mode — short passages translated on demand from the toolbar, editor, or block popovers. It uses a separate, lighter configuration from the full-page translation to keep responses fast and cost-effective.'=>'La traduzione rapida viene utilizzata in modalità snippet/pezzo — brevi passaggi tradotti su richiesta dalla barra degli strumenti, editor o popover dei blocchi. Utilizza una configurazione separata e più leggera rispetto alla traduzione a pagina intera per mantenere le risposte rapide e convenienti.','Re-enables Gutenberg\'s canLockBlocks. Useful for editorial templates that need to prevent contributors from moving or deleting specific blocks.'=>'Riabilita canLockBlocks di Gutenberg. Utile per modelli editoriali che devono impedire ai collaboratori di spostare o eliminare blocchi specifici.','Re-enables supportsTemplateMode. Core to Full-Site-Editing workflows where post-level template overrides are intentional.'=>'Riabilita supportsTemplateMode. Fondamentale per i flussi di lavoro di Full-Site-Editing in cui le override di modello a livello di post sono intenzionali.','Re-generates and updates the cached result.'=>'Rigenera e aggiorna il risultato memorizzato.','Re-scan'=>'Riscansione','Re-scanning…'=>'Riscansione…','Re-translate'=>'Ritraduci','Reading time'=>'Tempo di lettura','Redirect visitors to their preferred language based on the browser\'s Accept-Language header'=>'Reindirizza i visitatori alla loro lingua preferita in base all\'intestazione Accept-Language del browser','Refine further — e.g. "make it shorter" or "use a formal tone"…'=>'Raffina ulteriormente — ad esempio "rendilo più breve" o "usa un tono formale"…','Refine further:'=>'Raffina ulteriormente:','Refinement'=>'Rifinitura','Refinement failed — please try again.'=>'Rifinitura fallita — riprova.','Refining…'=>'Rifinendo…','Regenerates WordPress rewrite rules so URL prefixes, language-specific slugs, and archive rewrites are all in sync. Necessary after changing the primary language or adding new language support.'=>'Rigenera le regole di riscrittura di WordPress in modo che i prefissi URL, gli slug specifici della lingua e le riscritture degli archivi siano sincronizzati. Necessario dopo aver cambiato la lingua principale o aver aggiunto il supporto per nuove lingue.','Remove stored key'=>'Rimuovi chiave memorizzata','Repair assigns the source language to every affected post. Run after importing content or after initial plugin activation on an existing site.'=>'La riparazione assegna la lingua di origine a ogni post interessato. Esegui dopo aver importato contenuti o dopo l\'attivazione iniziale del plugin su un sito esistente.','Repair failed.'=>'Riparazione fallita.','Repair — assign _lf_lang = %s to all affected posts'=>'Riparazione — assegna _lf_lang = %s a tutti i post interessati','Repairing…'=>'Riparazione in corso…','Report an issue on GitHub'=>'Segnala un problema su GitHub','Request failed — please try again.'=>'Richiesta fallita — riprova.','Request failed.'=>'Richiesta fallita.','Request failed. Check your connection.'=>'Richiesta fallita. Controlla la connessione.','Request failed. Please try again.'=>'Richiesta fallita. Per favore riprova.','Requests'=>'Richieste','requests / day'=>'richieste / giorno','Reset'=>'Reimposta','Result will appear here…'=>'Il risultato apparirà qui…','Retranslate'=>'Retraduci','Retranslating…'=>'Retraduzione in corso…','Review carefully — links and slugs not updated.'=>'Revisiona attentamente — link e slug non aggiornati.','Review translation before applying'=>'Revisiona la traduzione prima di applicarla','Revise'=>'Rivedi','Revision'=>'Revisione','Revision Type'=>'Tipo di revisione','Rewrite Rules'=>'Regole di riscrittura','robots.txt'=>'robots.txt','robots.txt updated with Sitemap directive.'=>'robots.txt aggiornato con direttiva Sitemap.','Router'=>'Router','Router Tab'=>'Scheda Router','Run a full SEO audit across all published posts for one or all active languages. Scores are saved per post and reflected in the Language column badges in the post list.'=>'Esegui una verifica SEO completa su tutti i post pubblicati per una o tutte le lingue attive. I punteggi sono salvati per post e riflessi nelle etichette della colonna Lingua nell\'elenco dei post.','Run AI Analysis'=>'Esegui analisi IA','Save'=>'Salva','Save analysis settings'=>'Salva impostazioni di analisi','Save Debug Setting'=>'Salva impostazioni di debug','Save Hreflang Settings'=>'Salva impostazioni Hreflang','Save Open Graph Settings'=>'Salva impostazioni Open Graph','Save Router Settings'=>'Salva impostazioni del router','Save Schema.org Settings'=>'Salva impostazioni Schema.org','Save Settings'=>'Salva impostazioni','Save Sitemap Settings'=>'Salva impostazioni Sitemap','Save Social Share Settings'=>'Salva impostazioni di condivisione sociale','Save the post to persist changes.'=>'Salva il post per mantenere le modifiche.','Save Uninstall Setting'=>'Salva impostazione di disinstallazione','Save WooCommerce SEO Settings'=>'Salva impostazioni SEO WooCommerce','Saved to the meta description field when you apply.'=>'Salvata nel campo della meta descrizione quando applichi.','Scan failed: '=>'Scansione fallita: ','Scan request failed. Please try again.'=>'Richiesta di scansione fallita. Riprova.','Scanning posts for broken language links…'=>'Scansione dei post per link rotti…','Schema output deferred.'=>'Output Schema in attesa.','Schema.org'=>'Schema.org','Schema.org JSON-LD'=>'Schema.org JSON-LD','Schema.org output'=>'Output Schema.org','Schema.org settings saved.'=>'Impostazioni Schema.org salvate.','Score'=>'Punteggio','Scores are a signal, not a verdict. Some content is structurally limited — very short pages, landing pages with little body text, or pages whose purpose is navigation rather than information may score lower by nature. Use this overview to spot genuine parity gaps across languages, not to chase a number.'=>'I punteggi sono un segnale, non un verdetto. Alcuni contenuti sono limitati strutturalmente — pagine molto brevi, pagine di destinazione con poco testo, o pagine il cui scopo è la navigazione piuttosto che l\'informazione possono avere punteggi più bassi per natura. Usa questa panoramica per individuare effettive lacune di parità tra le lingue, non per inseguire un numero.','Search'=>'Ricerca','Search Console is useful for monitoring indexing and coverage errors, but is not required for discovery.'=>'Search Console è utile per monitorare errori di indicizzazione e copertura, ma non è necessario per la scoperta.','Search Results'=>'Risultati di ricerca','Security check failed — file path is not permitted.'=>'Controllo di sicurezza fallito — percorso del file non consentito.','See Settings → SEO → Compatibility for the full per-feature behaviour table.'=>'Vedi Impostazioni → SEO → Compatibilità per la tabella completa di comportamento per funzione.','Select a language to manage its FSE templates, template parts, and navigation menus.'=>'Seleziona una lingua per gestire i suoi modelli FSE, parti del modello e menu di navigazione.','Select a post and run a detailed SEO audit to see per-metric results and a score for that specific item.'=>'Seleziona un post e esegui una verifica SEO dettagliata per vedere i risultati per metrica e un punteggio per quell\'elemento specifico.','Select language'=>'Seleziona lingua','Send via Telegram'=>'Invia tramite Telegram','Send via WhatsApp'=>'Invia tramite WhatsApp','SEO'=>'SEO','SEO Analysis'=>'Analisi SEO','SEO character-count info'=>'Informazioni sul conteggio dei caratteri SEO','SEO plugin(s) detected: %s. LF is outputting og:locale and og:locale:alternate only; the detected plugin handles the full OG set.'=>'Plugin SEO rilevati: %s. LF sta visualizzando solo og:locale e og:locale:alternate; il plugin rilevato gestisce l\'intero set OG.','SEO Plugins'=>'Plugin SEO','SEO plugins and conflict avoidance:'=>'Plugin SEO e prevenzione dei conflitti:','SEO Tab'=>'Scheda SEO','Server setup (subdomain)'=>'Configurazione server (sottodominio)','Sets the default AI behaviour for all features site-wide. Individual posts can override this for Translation and Content Generation via the Lingua Forge meta box.'=>'Imposta il comportamento predefinito di AI per tutte le funzionalità nel sito. I singoli post possono sovrascrivere questo per Traduzione e Generazione di contenuti tramite la meta box di Lingua Forge.','Settings'=>'Impostazioni','Settings saved.'=>'Impostazioni salvate.','Settings → Permalinks'=>'Impostazioni → Permalink','Share on Facebook'=>'Condividi su Facebook','Share on LinkedIn'=>'Condividi su LinkedIn','Share on Mastodon'=>'Condividi su Mastodon','Share via email (mailto:)'=>'Condividi via email (mailto:)','Shop'=>'Negozio','Show home link'=>'Mostra link alla home','Shown when no translation exists for the visitor\'s language.'=>'Mostrato quando non esiste una traduzione per la lingua del visitatore.','Single'=>'Singolo','Single %s'=>'Singolo %s','Single-word title (%d chars) — adding a second word improves clarity and keyword coverage.'=>'Titolo di una sola parola (%d caratteri) — aggiungere una seconda parola migliora la chiarezza e la copertura delle parole chiave.','Single: %s'=>'Singolo: %s','Site-wide ceiling on AI requests per UTC day (counts both Toolbar translations and block revisions). Counter resets at UTC midnight. Set to 0 to disable the cap.'=>'Limite massimo di richieste IA per giorno UTC (include sia le traduzioni della toolbar che le revisioni dei blocchi). Il contatore si resetta a mezzanotte UTC. Imposta a 0 per disabilitare il limite.','Sitemap'=>'Mappa del sito','Sitemap cache flushed. It will be regenerated on the next visit to the sitemap URL.'=>'Cache della mappa del sito svuotata. Verrà rigenerata alla prossima visita all\'URL della mappa del sito.','Sitemap output'=>'Output della mappa del sito','Sitemap settings saved.'=>'Impostazioni della mappa del sito salvate.','Sitemap URL'=>'URL della mappa del sito','Size'=>'Dimensione','Social Icons block share: URLs: handled by LF\'s built-in Social Share (SEO → Social Share)'=>'Condivisione del blocco Icone social: URL: gestiti dal Social Share integrato di LF (SEO → Social Share)','Social Share'=>'Condivisione sociale','Social Share settings saved.'=>'Impostazioni di condivisione sociale salvate.','Some link fixes failed.'=>'Alcune correzioni di link non sono riuscite.','Some nav ref fixes failed.'=>'Alcune correzioni di riferimenti di navigazione non sono riuscite.','Some part fixes failed.'=>'Alcune correzioni di parti non sono riuscite.','Some parts could not be created.'=>'Alcune parti non sono state create.','Some templates could not be created.'=>'Alcuni modelli non sono stati creati.','Some translations failed.'=>'Alcune traduzioni non sono riuscite.','source'=>'origine','Source file not found.'=>'File di origine non trovato.','Source lang'=>'Lingua di origine','Source language'=>'Lingua di origine','Source term'=>'Termine di origine','Source title'=>'Titolo di origine','Standard'=>'Standard','Standard uses each feature\'s own tuned temperature: Translation T=0.2 (precise), Quick Translate T=0.4, Content Generator T=0.6 (creative). The other presets apply a single fixed temperature across all features.'=>'Standard utilizza la temperatura ottimizzata di ogni funzionalità: Traduzione T=0.2 (preciso), Traduzione rapida T=0.4, Generatore di contenuti T=0.6 (creativo). Gli altri preset applicano una temperatura fissa unica a tutte le funzionalità.','Status'=>'Stato','Status / Actions'=>'Stato / Azioni','Storytelling'=>'Storytelling','Strict-preservation mode for legal, regulatory, medical, or technical content. When on, every AI feature uses a low sampling temperature and appends the addendum below to its system prompt — terminology, article numbers, units, brand names, and regulatory language are preserved verbatim rather than paraphrased.'=>'Modalità di conservazione rigorosa per contenuti legali, regolamentari, medici o tecnici. Quando attivo, ogni funzionalità AI utilizza una temperatura di campionamento bassa e aggiunge il supplemento sotto al suo prompt di sistema — terminologia, numeri di articolo, unità, nomi di marca e linguaggio regolamentare sono preservati letteralmente anziché parafrasati.','Structured Outline'=>'Schema strutturato','Subdomain (de.example.com)'=>'Sottodominio (de.example.com)','Subdomain mode requires your web server to point all language subdomains (e.g. de.example.com) to this WordPress installation. After switching modes, flush permalink rules and clear any caches. If your home URL includes www (e.g. www.example.com), use the lf_base_domain filter to set the bare apex domain so subdomains are constructed correctly.'=>'La modalità sottodominio richiede che il tuo server web punti tutti i sottodomini di lingua (ad esempio de.example.com) a questa installazione di WordPress. Dopo aver cambiato modalità, aggiorna le regole dei permalink e svuota le cache. Se il tuo URL principale include www (ad esempio www.example.com), usa il filtro lf_base_domain per impostare il dominio apex nudo in modo che i sottodomini siano costruiti correttamente.','Subdomain — de.example.com/'=>'Sottodominio — it.example.com/','Submit this URL to Google Search Console alongside your main sitemap.'=>'Invia questa URL a Google Search Console insieme alla tua sitemap principale.','Submit to Reddit'=>'Invia a Reddit','Suggested meta description'=>'Meta description suggerita','Suggested title'=>'Titolo suggerito','Supported providers: Anthropic (Claude), OpenAI (GPT), Google (Gemini). Only one provider is active at a time. Select the active provider on the General tab.'=>'Provider supportati: Anthropic (Claude), OpenAI (GPT), Google (Gemini). Solo un provider è attivo alla volta. Seleziona il provider attivo nella scheda Generale.','Suppressed: %s.'=>'Soppresso: %s.','Switch to a post-name based structure in'=>'Passa a una struttura basata sul nome del post in','System'=>'Sistema','T=%s'=>'T=%s','T=0.2–0.6, per feature'=>'T=0.2–0.6, per funzionalità','Tag'=>'Tag','Tags emitted'=>'Tag emessi','Target lang'=>'Lingua di destinazione','Target Language'=>'Lingua di destinazione','Target language'=>'Lingua di destinazione','Target term'=>'Termine di destinazione','Target: 140–160 chars for optimal SERP display'=>'Target: 140–160 caratteri per una visualizzazione ottimale nei risultati di ricerca','Technical'=>'Tecnico','Technical / Scientific'=>'Tecnico / Scientifico','Technical / Scientific instructions'=>'Istruzioni tecniche / scientifiche','Template "%s" already exists.'=>'Il modello "%s" esiste già.','Template "{expected}" does not exist — create it in the Site Editor first.'=>'Il template "{expected}" non esiste — crealo prima nell\'Editor del sito.','Template has no content.'=>'Il modello non ha contenuto.','Template mode'=>'Modalità modello','Template not found or not stored in the database.'=>'Modello non trovato o non memorizzato nel database.','Template part "%s" already exists.'=>'Parte del modello "%s" esiste già.','Template part has no content.'=>'La parte del modello non ha contenuto.','Template part not found or not stored in the database.'=>'Parte del modello non trovata o non memorizzata nel database.','Template Parts'=>'Parti del modello','Templates'=>'Modelli','Test connection'=>'Testa la connessione','Testing…'=>'Test in corso…','Text domain / locale'=>'Dominio del testo / locale','Text to translate'=>'Testo da tradurre','The API Response Cache stores the raw result of every AI request — translation, meta description, excerpt, and content generation — keyed by a hash of the inputs (content, language pair, provider, model). Disable during prompt tuning or when you need every request to reach the AI provider. Disabling does not delete cached entries — re-enabling restores them.'=>'La cache di risposta API memorizza il risultato grezzo di ogni richiesta AI — traduzione, meta descrizione, estratto e generazione di contenuti — identificato da un hash degli input (contenuto, coppia di lingue, provider, modello). Disattiva durante la messa a punto del prompt o quando hai bisogno che ogni richiesta raggiunga il provider AI. Disattivare non elimina le voci memorizzate — riattivare le ripristina.','The editor did not accept the content — please try again.'=>'L\'editor non ha accettato il contenuto — riprova.','The following directive is active in your virtual robots.txt:'=>'La seguente direttiva è attiva nel tuo robots.txt virtuale:','The lf-social-share mu-plugin is active.'=>'Il plugin mu lf-social-share è attivo.','The lf-social-share mu-plugin is active. Lingua Forge\'s built-in Social Share is inactive — the mu-plugin handles share URL rewriting and the JS actions.'=>'Il plugin mu lf-social-share è attivo. La funzione Social Share integrata di Lingua Forge è inattiva — il plugin gestisce la riscrittura degli URL di condivisione e le azioni JS.','The Light tier uses the fast model configured in the Models table above (default: Haiku / Flash). Switch to Quality if you need the same translation accuracy as full-page mode for snippets.'=>'Il livello Light utilizza il modello rapido configurato nella tabella Modelli sopra (predefinito: Haiku / Flash). Passa a Qualità se hai bisogno della stessa precisione di traduzione della modalità a pagina intera per gli snippet.','The phrase as it appears in the source text.'=>'La frase così come appare nel testo di origine.','The primary language is always served at the root of your site — no URL prefix in path mode, no language subdomain in subdomain mode. All other languages use either a /lang/ path prefix (e.g. example.com/de/) or a language subdomain (e.g. de.example.com), depending on the URL structure setting below.'=>'La lingua principale viene sempre servita alla radice del tuo sito — nessun prefisso URL in modalità percorso, nessun sottodominio di lingua in modalità sottodominio. Tutite le altre lingue usano un prefisso di percorso /lang/ (esempio: example.com/de/) o un sottodominio di lingua (esempio: de.example.com), a seconda dell\'impostazione della struttura URL sottostante.','The SEO → Compatibility tab shows the live detection status and explains exactly what LF is doing for each feature area.'=>'La scheda SEO → Compatibilità mostra lo stato di rilevamento in tempo reale e spiega esattamente cosa fa LF per ogni area di funzionalità.','The share URL always reflects the current page — no manual URL entry needed. The linguaforge_social_share_url filter lets you override the resolved URL for any service.'=>'L\'URL di condivisione riflette sempre la pagina corrente — nessun inserimento manuale di URL necessario. Il filtro linguaforge_social_share_url permette di sovrascrivere l\'URL risolto per qualsiasi servizio.','The sitemap is announced in robots.txt automatically. All major search engines — Google, Bing, Yandex — discover it from robots.txt. No manual submission is required.'=>'La sitemap viene annunciata automaticamente in robots.txt. Tutti i principali motori di ricerca — Google, Bing, Yandex — la scoprono dal robots.txt. Non è richiesta una sottomissione manuale.','The source page has no footnotes.'=>'La pagina di origine non ha note a piè di pagina.','The upload failed — please try again.'=>'Il caricamento è fallito — riprova.','The WordPress core sitemap lists all your content URLs. The LF sitemap tells search engines how language versions relate to each other via xhtml:link hreflang alternates. Submit both to Google Search Console for full coverage.'=>'La sitemap di WordPress elenca tutti gli URL dei tuoi contenuti. La sitemap LF indica ai motori di ricerca come le versioni linguistiche si relazionano tra loro tramite gli alternati xhtml:link hreflang. Invia entrambe a Google Search Console per una copertura completa.','These footnotes come from the source page and are shown here for reference only. Add them to this page using the block editor.'=>'Queste note a piè di pagina provengono dalla pagina di origine e sono mostrate qui solo a scopo di riferimento. Aggiungile a questa pagina usando l\'editor a blocchi.','This is a WooCommerce system page (Shop, Cart, Checkout, etc.). Its content is managed by WooCommerce — the score reflects structural signals only, not user-editable SEO content.'=>'Questa è una pagina di sistema WooCommerce (Negozio, Carrello, Pagamento, ecc.). Il suo contenuto è gestito da WooCommerce — il punteggio riflette solo segnali strutturali, non contenuti SEO modificabili dall\'utente.','This is the source page. Footnotes are edited directly in the block editor.'=>'Questa è la pagina di origine. Le note a piè di pagina vengono modificate direttamente nell\'editor a blocchi.','This key is currently supplied by a server %s and cannot be removed here. Enter a new key above to override it with a database value.'=>'Questa chiave è attualmente fornita da un server %s e non può essere rimossa qui. Inserisci una nuova chiave sopra per sovrascriverla con un valore del database.','This language is protected and cannot be uninstalled.'=>'Questa lingua è protetta e non può essere disinstallata.','This language matches the WordPress instance locale and cannot be uninstalled.'=>'Questa lingua corrisponde alla locale dell\'istanza WordPress e non può essere disinstallata.','Tip: to reset a model to the built-in default, clear the field and save.'=>'Suggerimento: per ripristinare un modello al default integrato, cancella il campo e salva.','Title'=>'Titolo','Title is %1$d chars — may be truncated in SERPs (aim for under %2$d).'=>'Il titolo è %1$d caratteri — potrebbe essere troncato nei risultati di ricerca (punta a meno di %2$d).','Title is only %d chars — aim for more than 10 characters.'=>'Il titolo è di soli %d caratteri — mira a più di 10 caratteri.','To use a custom encryption secret (instead of the derived wp_salt value), add this to wp-config.php:'=>'Per usare un segreto di crittografia personalizzato (invece del valore derivato wp_salt), aggiungi questo a wp-config.php:','Today'=>'Oggi','Token consumption rolled up by feature, provider, and model. Recorded on every successful AI call; Test Connection pings are excluded so they don\'t skew the totals.'=>'Il consumo di token aggregato per funzionalità, provider e modello. Registrato ad ogni chiamata AI riuscita; i ping di Test Connection sono esclusi per non distorcere i totali.','Tone'=>'Tono','tone'=>'tono','Tone:'=>'Tono:','Too many AI requests. Please retry in %d seconds.'=>'Troppi richieste AI. Riprova tra %d secondi.','Total'=>'Totale','Total tokens'=>'Token totali','Translate'=>'Traduci','Translate / Revise'=>'Traduci / Rivedi','Translate / Revise block'=>'Blocca di traduzione / revisione','Translate all'=>'Traduci tutto','Translate chunk'=>'Traduci blocco','Translate Content'=>'Traduci contenuto','Translate missing'=>'Traduzione mancante','Translate page…'=>'Traduci pagina…','Translated content'=>'Contenuto tradotto','Translated Names'=>'Nomi tradotti','Translated title'=>'Titolo tradotto','Translated to:'=>'Tradotto in:','Translated. Review in the Site Editor — internal links, navigation URLs, and template slugs are not updated automatically.'=>'Tradotto. Rivedi nell\'Editor del sito — i link interni, gli URL di navigazione e gli slug dei template non vengono aggiornati automaticamente.','Translating…'=>'Traduzione in corso…','Translation'=>'Traduzione','Translation Caching'=>'Caching della traduzione','Translation found but permalink could not be generated'=>'Traduzione trovata ma il permalink non può essere generato','Translation Limits'=>'Limiti di traduzione','Translation Limits & Behavior'=>'Limiti e comportamento della traduzione','Translation Limits: control which user roles can trigger AI translation, and set a monthly token budget. Exceeding the budget suspends AI calls until the month resets.'=>'Limiti di traduzione: controlla quali ruoli utente possono attivare la traduzione AI e imposta un budget mensile di token. Superare il budget sospende le chiamate AI fino al reset del mese.','Translation Memory'=>'Memoria di traduzione','Translation Memory caches AI results by content hash, language pair, provider, and model. Editing a post invalidates the cache entry so the next translate call gets a fresh result.'=>'La cache della memoria di traduzione memorizza i risultati dell\'IA per hash del contenuto, coppia di lingue, provider e modello. Modificare un post invalida la voce della cache in modo che la prossima chiamata di traduzione ottenga un risultato aggiornato.','Translation Memory cleared. %d cached block was removed.'=>'Memoria di traduzione cancellata. %d blocco memorizzato nella cache è stato rimosso.' . "\0" . 'Memoria di traduzione cancellata. %d blocchi memorizzati nella cache sono stati rimossi.','Translation Memory setting saved.'=>'Impostazione della memoria di traduzione salvata.','Translation Memory: stores the full translated post per content hash. Clear it when you want to force a retranslation of all posts regardless of whether their content changed.'=>'Memoria di traduzione: memorizza l\'intero post tradotto per hash del contenuto. Pulisci questa cache quando vuoi forzare una ritraduzione di tutti i post, indipendentemente dal fatto che il loro contenuto sia cambiato.','Translation workflow'=>'Workflow di traduzione','Translation, Content Generator'=>'Traduzione, Generatore di contenuti','Treat H2 as H1 equivalent'=>'Tratta H2 come equivalente a H1','Type'=>'Tipo','Uli Hake'=>'Uli Hake','Uninstall %s'=>'Disinstalla %s','Uninstall Behaviour'=>'Disinstalla comportamento','Uninstall setting saved.'=>'Impostazione di disinstallazione salvata.','unknown error'=>'errore sconosciuto','Unknown provider.'=>'Provider sconosciuto.','Unknown search engine.'=>'Motore di ricerca sconosciuto.','Unlike hreflang — where LF always overrides other plugins because they cannot know your multilingual configuration — Open Graph is different: Yoast, Rank Math, and similar plugins already output correct OG tags for your content. Duplicating them adds no value. In auto mode, LF detects active SEO plugins and adds only what they cannot provide: og:locale (current language) and og:locale:alternate (all other configured languages).'=>'A differenza di hreflang — dove LF sovrascrive sempre altri plugin perché non possono conoscere la tua configurazione multilingue — Open Graph è diverso: plugin come Yoast, Rank Math e simili già producono tag OG corretti per i tuoi contenuti. Duplicarli non aggiunge valore. In modalità automatica, LF rileva i plugin SEO attivi e aggiunge solo ciò che non possono fornire: og:locale (lingua corrente) e og:locale:alternate (tutte le altre lingue configurate).','Unlimited'=>'Illimitato','Up'=>'Su','Upload .mo file'=>'Carica file .mo','Upload compiled .mo files to override third-party plugin strings for specific locales — for example, a custom VikBooking translation that uses "apartment" instead of "room". Files must follow the WordPress naming convention: {textdomain}-{locale}.mo (e.g. vikbooking-ca.mo). They are stored in the uploads folder and survive plugin updates.'=>'Carica file .mo compilati per sovrascrivere le stringhe del plugin di terze parti per localizzazioni specifiche — ad esempio, una traduzione personalizzata di VikBooking che usa "appartamento" invece di "camera". I file devono seguire la convenzione di denominazione di WordPress: {textdomain}-{locale}.mo (esempio: vikbooking-ca.mo). Sono archiviati nella cartella uploads e sopravvivono agli aggiornamenti del plugin.','Upload Override'=>'Carica Sovrascrittura','URL could not be mapped to a post — check the link target exists'=>'L\'URL non può essere mappato a un post — verifica che il target del link esista','URL structure'=>'Struttura URL','URL structure: path-prefix mode (example.com/de/) requires no server changes. Subdomain mode (de.example.com) requires a wildcard DNS record, a wildcard SSL certificate, and a web server configuration change — see the Server Setup guide.'=>'Struttura URL: modalità prefisso percorso (example.com/de/) che non richiede modifiche al server. Modalità sottodominio (de.example.com) che richiede un record DNS wildcard, un certificato SSL wildcard e una modifica alla configurazione del server web — vedi la guida alla configurazione del server.','URL to enter'=>'URL da inserire','Use native share when available; fall back to clipboard copy. Recommended default for "Share" buttons.'=>'Usa la condivisione nativa quando disponibile; altrimenti copia negli appunti. Default raccomandato per i pulsanti "Condividi".','Use the tabs across the top of this page to configure each area. Changes to the Router tab take effect immediately; changes to AI keys and model settings apply to the next AI request.'=>'Usa le schede in alto a questa pagina per configurare ogni area. Le modifiche alla scheda Router hanno effetto immediato; le modifiche alle chiavi AI e alle impostazioni del modello si applicano alla prossima richiesta AI.','User-managed terminology table per language pair. Entries are appended to the translation system prompt so the AI uses preferred terms consistently — critical for domain vocabulary ("kWp", "PPA", "interconnection point"), brand names that must not translate, and standardised regulatory phrasing. Both language fields are optional: leave "Source language" blank to apply the entry regardless of which language you are translating from; leave "Target language" blank to apply it to all target languages at once.'=>'Tabella terminologica gestita dall\'utente per coppia di lingue. Le voci vengono aggiunte al prompt del sistema di traduzione affinché l\'IA utilizzi termini preferiti in modo coerente — fondamentale per il vocabolario di dominio ("kWp", "PPA", "punto di interconnessione"), nomi di marca che non devono essere tradotti e formulazioni normative standardizzate. Entrambi i campi della lingua sono opzionali: lasciare vuoto "Lingua di origine" per applicare la voce indipendentemente dalla lingua da cui si traduce; lasciare vuoto "Lingua di destinazione" per applicarla a tutte le lingue di destinazione contemporaneamente.','Using custom meta description.'=>'Utilizzo di meta descrizione personalizzata.','Using LF AI meta description.'=>'Utilizzo della meta descrizione AI di LF.','Value source'=>'Origine del valore','View'=>'Visualizza','View built-in default'=>'Visualizza default integrato','View current robots.txt'=>'Visualizza il robots.txt attuale','View details'=>'Visualizza dettagli','View Lingua Forge details'=>'Visualizza dettagli Lingua Forge','Visit plugin site'=>'Visita il sito del plugin','Warning:'=>'Avviso:','WcPageBridge active'=>'WcPageBridge attivo','WebSite'=>'Sito Web','WebSite — front page / blog index'=>'Sito Web — pagina principale / indice del blog','What LF provides — and collision avoidance'=>'Cosa fornisce LF — e prevenzione delle collisioni','What LF provides: hreflang tags for every configured language, Open Graph and Twitter Card tags with og:locale and og:locale:alternate, Schema.org JSON-LD with inLanguage annotations, and a dedicated multilingual sitemap at /lf-sitemap.xml with xhtml:link alternate entries for all translation groups.'=>'Cosa fornisce LF: tag hreflang per ogni lingua configurata, tag Open Graph e Twitter Card con og:locale e og:locale:alternate, Schema.org JSON-LD con annotazioni inLanguage, e una sitemap multilingue dedicata a /lf-sitemap.xml con voci alternate xhtml:link per tutti i gruppi di traduzione.','When another SEO plugin is installed'=>'Quando è installato un altro plugin SEO','When debug logging is enabled (via the toggle below or by defining LINGUAFORGE_AI_DEBUG in wp-config.php), the Translation and FSE template translation features write their raw AI prompts and responses to disk for troubleshooting. Use this section to monitor that output and clear it once you have what you need — the files can grow quickly on large pages. Configure the destination directory via the linguaforge_debug_dir filter.'=>'Quando il debug logging è abilitato (tramite l\'interruttore qui sotto o definendo LINGUAFORGE_AI_DEBUG in wp-config.php), le funzioni di traduzione e di traduzione dei modelli FSE scrivono le loro richieste AI e le risposte su disco per la risoluzione dei problemi. Usa questa sezione per monitorare quell\'output e cancellarlo una volta ottenuto ciò di cui hai bisogno — i file possono crescere rapidamente su pagine grandi. Configura la directory di destinazione tramite il filtro linguaforge_debug_dir.','When enabled, first-time visitors with no language cookie and no language prefix in the URL are redirected to the closest matching language version. The redirect is skipped if the browser\'s preferred language is not among the active router languages. Once a visitor selects a language via the switcher, the cookie takes priority and the browser header is ignored on all future visits.'=>'Quando abilitato, i visitatori alla prima visita senza cookie di lingua e senza prefisso di lingua nell\'URL vengono reindirizzati alla versione linguistica più vicina. Il reindirizzamento viene saltato se la lingua preferita dal browser non è tra le lingue attive del router. Una volta che un visitatore seleziona una lingua tramite il switcher, il cookie ha priorità e l\'intestazione del browser viene ignorata in tutte le visite future.','When enabled, Lingua Forge outputs the following additional meta tags on product pages: og:type=product, og:price:amount, og:price:currency, og:availability, and their product: namespace equivalents used by Facebook Catalog.'=>'Quando attivo, Lingua Forge produce i seguenti meta tag aggiuntivi nelle pagine prodotto: og:type=product, og:price:amount, og:price:currency, og:availability, e i loro equivalenti nel namespace product usati da Facebook Catalog.','When enabled, the sitemap URL is announced in robots.txt automatically and the cache is refreshed when translated content is saved.'=>'Quando attivo, l\'URL della sitemap viene annunciato automaticamente in robots.txt e la cache viene aggiornata quando il contenuto tradotto viene salvato.','When Yoast SEO, Rank Math, All in One SEO, or SEOPress is active, Lingua Forge automatically suppresses their hreflang output via filter. General SEO plugins produce hreflang based on a single-language URL structure and cannot account for your multilingual routing configuration; LF\'s output is always correct.'=>'Quando sono attivi Yoast SEO, Rank Math, All in One SEO o SEOPress, Lingua Forge sopprime automaticamente la loro produzione di hreflang tramite filtro. I plugin SEO generali producono hreflang basati su URL a singola lingua e non possono considerare la tua configurazione di routing multilingue; l\'output di LF è sempre corretto.','Which model tier to use for full-page translation. Quality uses the model configured in the Models table above and is recommended for accurate, long-form translation. Switch to Light only if speed or cost is the priority and the content is short.'=>'Quale livello di modello usare per la traduzione di pagine complete. La qualità utilizza il modello configurato nella tabella Modelli sopra ed è raccomandata per traduzioni accurate e di lunga durata. Passa a Leggero solo se la velocità o il costo sono prioritari e il contenuto è breve.','While active, the mu-plugin handles the base OG set and LF emits locale tags only (auto mode). Removing it switches LF to full OG mode automatically.'=>'Mentre è attivo, il plugin mu gestisce il set base OG e LF emette solo tag di localizzazione (modalità automatica). Rimuoverlo passa LF automaticamente alla modalità OG completa.','WooCommerce'=>'WooCommerce','WooCommerce is not active.'=>'WooCommerce non è attivo.','WooCommerce page translations'=>'Traduzioni delle pagine WooCommerce','WooCommerce product price'=>'Prezzo del prodotto WooCommerce','WooCommerce SEO settings saved.'=>'Impostazioni SEO di WooCommerce salvate.','WooCommerce store currency'=>'Valuta del negozio WooCommerce','WooCommerce system pages (Shop, Cart, Checkout, My Account) are excluded — their content is managed by WooCommerce and cannot be improved through SEO edits.'=>'Le pagine di sistema WooCommerce (Negozio, Carrello, Pagamento, Il mio account) sono escluse — il loro contenuto è gestito da WooCommerce e non può essere migliorato tramite modifiche SEO.','WooCommerce version'=>'Versione WooCommerce','Word count'=>'Conteggio parole','WordPress version'=>'Versione di WordPress','WP core canonical active (hreflang disabled)'=>'Canonical core di WP attivo (hreflang disattivato)','WP-CLI reference'=>'Riferimento WP-CLI','Write AI prompts and responses to disk for troubleshooting'=>'Scrivi richieste e risposte AI su disco per la risoluzione dei problemi','XML Sitemap'=>'Sitemap XML','Yes'=>'Sì','You can also define keys as constants or environment variables (e.g. in wp-config.php). Those sources are used automatically as a fallback when no database key is stored.'=>'Puoi anche definire le chiavi come costanti o variabili d\'ambiente (ad esempio in wp-config.php). Queste fonti vengono utilizzate automaticamente come fallback quando nessuna chiave del database è memorizzata.','You do not have permission to manage these settings.'=>'Non hai il permesso di gestire queste impostazioni.','You do not have permission to read this post.'=>'Non hai il permesso di leggere questo post.','{n} stale path(s)'=>'{n} percorso(i) obsoleto(i)','~%d min read'=>'~%d minuti di lettura' . "\0" . '~%d minuti di lettura','— Any source language —'=>'— Qualsiasi lingua di origine —','— Any target language —'=>'— Qualsiasi lingua di destinazione —','— Any target —'=>'— Qualsiasi destinazione —','— Any —'=>'— Qualsiasi —','— Auto-detect —'=>'— Rilevamento automatico —','— auto-detect —'=>'— rilevamento automatico —','— Deferred to plugin'=>'— Rinviato al plugin','— Disabled'=>'— Disattivato','— Not detected'=>'— Non rilevato','— select a language —'=>'— seleziona una lingua —','← Back'=>'← Indietro','↑ Detected from current post'=>'↑ Rilevato dal post attuale','→ Locale tags only (manual setting)'=>'→ Solo tag di localizzazione (impostazione manuale)','→ Locale tags only — deferring base OG to plugin'=>'→ Solo tag di localizzazione — rinvia la OG di base al plugin','↺ Re-translate'=>'↺ Ritraduci','↺ Refine'=>'↺ Raffina','↺ Refresh'=>'↺ Aggiorna','↺ Refresh AI Analysis'=>'↺ Aggiorna analisi AI','↺ Refreshing…'=>'↺ Aggiornamento…','⚠ Borderline'=>'⚠ Limite','⚠ No <strong>{lang}</strong> posts found. Make sure all translated posts have their Language meta set to <strong>{lang}</strong> in the Language metabox.'=>'⚠️ Nessun post <strong>{lang}</strong> trovato. Assicurati che tutti i post tradotti abbiano impostato il meta Lingua su <strong>{lang}</strong> nel metabox Lingua.','⚠ No changes'=>'⚠️ Nessun cambiamento','⚠ No changes — re-scan?'=>'⚠️ Nessun cambiamento — riscaricare?','✅ Fixed ({n})'=>'✅ Corretto ({n})','✅ No broken links or template mismatches found for <strong>{lang}</strong>. Scanned <strong>{scanned}</strong> post(s) and page(s) — all checks passed. Template part links (header, footer, sidebar) are not included here — use the Fix Template Parts button to check those separately.'=>'✅ Nessun link rotto o incongru